const fs = require('fs');
const path = require('path');

const results = JSON.parse(fs.readFileSync('lint_results_utf8.json', 'utf8').replace(/^\uFEFF/, ''));

const relevantDirs = ['(procurement)', 'inventory', 'master-data'];

const filteredResults = results.filter(file => {
  const filePath = file.filePath.replace(/\\/g, '/');
  return relevantDirs.some(dir => filePath.includes(dir));
}).map(file => ({
  filePath: file.filePath,
  messages: file.messages.filter(msg => msg.severity === 1) // Only warnings
})).filter(file => file.messages.length > 0);

console.log(JSON.stringify(filteredResults, null, 2));

"use client"

import * as React from "react";
import { useStocktake, useUpdateItemCount, useCompleteCounting } from "@/features/operations/api/useStocktakes";
import { useWarehouses } from "@/features/warehouses/api/useWarehouses";
import { useTranslations } from "next-intl";
import { useDebouncedCallback } from "use-debounce";
import { useRouter } from "@/i18n/navigation";
import { Loader2 } from "lucide-react";
import { toast } from "sonner";
import { useUnsavedChangesGuard } from "@/lib/unsaved-changes/useUnsavedChangesGuard";
import { useVirtualizer } from "@tanstack/react-virtual";
import { mapToSessionVM, StocktakeItemVM } from "@/features/operations/mappers/stocktakeMapper";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { PageHeader } from "@/components/shared/PageHeader";
import { ScanInput } from "@/components/shared/ScanInput/ScanInput";
import { PermissionGate } from "@/components/shared/PermissionGate";
import { PageSkeleton } from "@/components/shared/PageSkeleton";
import { ErrorState } from "@/components/shared/ErrorState";
import { StatusBadge } from "@/components/shared/StatusBadge";

import { ActionGuard } from "@/core/workflow/ActionGuard";
import { isStocktakeCounting } from "@/domain/status-guards";
import { STOCKTAKE_STATUS_UI } from "@/domain/status-ui-map";
import { useAbortController } from "@/hooks/useAbortController";

export function StocktakeCountClient({ id, locale }: { id: string, locale: 'ar' | 'en' }) {
  const t = useTranslations('operations.stocktake')
  const common = useTranslations('common')
  const baseRouter = useRouter();
  const { router: guardedRouter } = useUnsavedChangesGuard(false);
  const abortController = useAbortController();
  const { data: rawSession, isLoading: sessionLoading, error: sessionError } = useStocktake(id);
  const session = rawSession ? mapToSessionVM(rawSession) : null;
  const { data: warehouses, isLoading: isLoadingWarehouses, error: errorWarehouses } = useWarehouses();
  const updateCount = useUpdateItemCount();
  const completeCounting = useCompleteCounting();

  const [scanStatus, setScanStatus] = React.useState<"idle" | "success" | "error">("idle")
  const [statusMessage, setStatusMessage] = React.useState("")
  const [localCounts, setLocalCounts] = React.useState<Record<string, number>>({})
  const [focusedRowIndex, setFocusedRowIndex] = React.useState<number>(-1)
  
  const parentRef = React.useRef<HTMLDivElement>(null)
  const inputRefs = React.useRef<Map<number, HTMLInputElement>>(new Map())

  const items = session?.items || []

  const rowVirtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 88,
    overscan: 10,
  })

  // Synchronize focus when index changes
  React.useEffect(() => {
    if (focusedRowIndex !== -1) {
      rowVirtualizer.scrollToIndex(focusedRowIndex, { align: 'center' });
      // Small timeout to allow virtualization to render the row
      const timer = setTimeout(() => {
        const input = inputRefs.current.get(focusedRowIndex);
        if (input) {
          input.focus();
          input.select(); // Better UX for editing
        }
      }, 50);
      return () => clearTimeout(timer);
    }
  }, [focusedRowIndex, rowVirtualizer]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setFocusedRowIndex(prev => Math.min(prev + 1, items.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setFocusedRowIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Escape') {
      setFocusedRowIndex(-1);
      (document.activeElement as HTMLElement)?.blur();
    } else if (e.key === 'Enter') {
      // If we are in an input, move to next row
      if (e.target instanceof HTMLInputElement && e.target.type === 'number') {
        e.preventDefault();
        if (focusedRowIndex < items.length - 1) {
          setFocusedRowIndex(prev => prev + 1);
        } else {
          toast.info(t('last_item_reached'));
        }
      }
    }
  };

  const debouncedUpdate = useDebouncedCallback(
    (itemId: string, lineId: string, countedQty: number) => {
      updateCount.mutate({ stocktakeId: id, itemId, lineId, countedQty, signal: abortController.signal })
    },
    800
  )

  const isInitialized = React.useRef(false)
  React.useEffect(() => {
    if (session?.items && !isInitialized.current) {
      const counts: Record<string, number> = {}
      session.items.forEach((i) => {
        counts[i.id] = i.countedQty || 0
      })
      setLocalCounts(counts)
      isInitialized.current = true
    }
  }, [session?.items])

  if (sessionLoading || isLoadingWarehouses) return <PageSkeleton variant="list" />;
  if (sessionError || errorWarehouses || !session) return <ErrorState onRetry={() => window.location.reload()} />;
  
  const warehouse = warehouses?.find((w) => w.id === session.warehouseId);
  const warehouseName = warehouse ? (locale === 'ar' ? warehouse.name_ar : warehouse.name_en) : (session.warehouseName || session.warehouseId);

  if (!isStocktakeCounting(session.status)) {
    baseRouter.replace(`/stocktake/${id}`);
    return null;
  }

  const handleScan = async (barcode: string) => {
    const index = items.findIndex((i) => i.barcode === barcode)
    if (index !== -1) {
      const item = items[index] as StocktakeItemVM
      const currentQty = localCounts[item.id] || 0
      const newQty = currentQty + 1
      
      setLocalCounts(prev => ({ ...prev, [item.id]: newQty }))
      updateCount.mutate({ stocktakeId: id, itemId: item.itemId, lineId: item.id, countedQty: newQty, signal: abortController.signal })
      
      setScanStatus("success")
      setStatusMessage(`${item.itemName}: ${newQty}`)
      
      // Focus the scanned row for immediate verification
      setFocusedRowIndex(index)

      setTimeout(() => {
        setScanStatus("idle")
        setStatusMessage("")
      }, 2000)
    } else {
      setScanStatus("error")
      setStatusMessage(t('no_item_found'))
      setTimeout(() => {
        setScanStatus("idle")
        setStatusMessage("")
      }, 3000)
    }
  }

  const handleFinish = () => {
    completeCounting.mutate({ id, signal: abortController.signal }, {
      onSuccess: () => {
        toast.success(t('posted_success'))
        guardedRouter.push(`/stocktake/${id}/variance`, { skipGuard: true })
      },
      onError: () => {
        toast.error(common('error'))
      }
    })
  }

  const hasCountedItems = session.items.some((i) => (localCounts[i.id] || 0) > 0)

  const virtualRows = rowVirtualizer.getVirtualItems();
  const totalSize = rowVirtualizer.getTotalSize();
  const paddingTop = virtualRows.length > 0 ? virtualRows[0]?.start || 0 : 0;
  const paddingBottom =
    virtualRows.length > 0
      ? totalSize - (virtualRows[virtualRows.length - 1]?.end || 0)
      : 0;

  return (
    <PermissionGate action="edit" resource="operations_stocktake">
      <div className="space-y-6" onKeyDown={handleKeyDown}>
        <PageHeader
          title={session.sessionName}
          subtitle={warehouseName}
          backHref={`/stocktake/${id}`}
        >
          <div className="flex items-center gap-4">
            {updateCount.isPending && (
              <div className="flex items-center gap-2 text-label-sm text-muted-foreground animate-pulse">
                <Loader2 className="h-3 w-3 animate-spin" />
                {t('autosave_active')}
              </div>
            )}
            <StatusBadge 
              status={session.status} 
              configMap={STOCKTAKE_STATUS_UI}
              className="h-9 px-4 text-label-xs font-semibold border-none" 
            />
            <ActionGuard
              documentType="STOCKTAKE"
              action="SUBMIT"
              status={session.status}
              onConfirm={handleFinish}
              trigger={
                <Button 
                  disabled={!hasCountedItems || completeCounting.isPending}
                  className="primary-gradient shadow-lg shadow-primary/20"
                >
                  {completeCounting.isPending && (
                    <Loader2 className="h-4 w-4 animate-spin me-2" />
                  )}
                  {t('finish_counting')}
                </Button>
              }
            />
          </div>
        </PageHeader>

        <div className="max-w-2xl mx-auto w-full">
          <ScanInput
            onScan={handleScan}
            scanStatus={scanStatus}
            statusMessage={statusMessage}
            placeholder={t('scan_barcode_to_count')}
            label={t('scan_session')}
            scannerMode={true}
          />
        </div>

        <Card className="p-10 bg-surface-container-low border-none shadow-none rounded-[2.5rem]">
          <div 
            ref={parentRef}
            className="rounded-3xl bg-white/[0.01] overflow-auto max-h-[600px] relative"
          >
            <Table>
              <TableHeader className="bg-white/[0.02] sticky top-0 z-10">
                <TableRow className="hover:bg-transparent border-none">
                  <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 h-12 px-8 w-[40%]">{common('item')}</TableHead>
                  <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 h-12 w-[30%]">{t('details')}</TableHead>
                  <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 text-center h-12 w-[20%]">{t('counted_qty')}</TableHead>
                  <TableHead className="text-label-xs font-semibold uppercase text-muted-foreground/40 text-end h-12 px-8 w-[10%]">{common('uom')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {paddingTop > 0 && (
                  <TableRow style={{ height: `${paddingTop}px` }} className="hover:bg-transparent border-none">
                    <TableCell colSpan={4} className="p-0" />
                  </TableRow>
                )}
                {virtualRows.map((virtualRow) => {
                  const item = items[virtualRow.index];
                  const isFocused = focusedRowIndex === virtualRow.index;

                  return (
                    <TableRow
                      key={item.id}
                      className={cn(
                        "transition-colors border-none group",
                        isFocused && "bg-primary/5 ring-1 ring-primary/20"
                      )}
                      style={{
                        height: `${virtualRow.size}px`,
                      }}
                    >
                        <TableCell className="px-8 py-6">
                          <div className="flex flex-col gap-1">
                            <span className="font-semibold text-foreground group-hover:text-primary transition-colors">{item.itemName}</span>
                            <span className="text-label-xs font-semibold text-muted-foreground/40 font-mono" dir="ltr">{item.barcode}</span>
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="flex flex-col gap-1">
                            <span className="text-body-md font-mono font-semibold text-muted-foreground/60" dir="ltr">{item.lotNumber}</span>
                            <span className="text-label-xs font-semibold text-muted-foreground/30 uppercase" dir="ltr">{item.expiryDate}</span>
                          </div>
                        </TableCell>
                        <TableCell>
                          <Input
                            ref={(el) => {
                              if (el) inputRefs.current.set(virtualRow.index, el);
                              else inputRefs.current.delete(virtualRow.index);
                            }}
                            type="number"
                            value={localCounts[item.id] ?? ''} 
                            onFocus={() => setFocusedRowIndex(virtualRow.index)}
                            onChange={(e) => {
                              const val = parseFloat(e.target.value) || 0
                              setLocalCounts(prev => ({ ...prev, [item.id]: val }))
                              debouncedUpdate(item.itemId, item.id, val)
                            }}
                            className={cn(
                              "text-center font-mono font-semibold h-10 bg-surface-container-medium border-none focus-visible:ring-1 transition-all rounded-lg",
                              isFocused ? "focus-visible:ring-primary" : "focus-visible:ring-primary/30"
                            )}
                            dir="ltr"
                          />
                        </TableCell>
                        <TableCell className="text-end px-8 font-semibold text-label-xs text-muted-foreground/40 uppercase">
                          {item.uom}
                        </TableCell>
                    </TableRow>
                  );
                })}
                {paddingBottom > 0 && (
                  <TableRow style={{ height: `${paddingBottom}px` }} className="hover:bg-transparent border-none">
                    <TableCell colSpan={4} className="p-0" />
                  </TableRow>
                )}
              </TableBody>
            </Table>
            {items.length === 0 && (
              <div className="h-32 flex items-center justify-center text-muted-foreground italic">
                {t('no_items_counted')}
              </div>
            )}
          </div>
        </Card>
      </div>
    </PermissionGate>
  )
}

import { getTranslations } from "next-intl/server";
import { StocktakeStartClient } from "./StocktakeStartClient";

export default async function StocktakeStartPage({
 params
}: {
 params: Promise<{ locale: 'ar' | 'en'; id: string }>;
}) {
 const { locale, id } = await params;
 
 return (
 <StocktakeStartClient id={id} locale={locale} />
 );
}

"use client";

import * as React from "react";
import { useForm, useWatch } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { useUnsavedChangesGuard } from "@/lib/unsaved-changes/useUnsavedChangesGuard";
import { useState } from "react";
import { useTranslations } from "next-intl";
import { 
 ArrowLeft, 
 Warehouse, 
 FileText, 
 Settings2,
 ChevronRight,
 ClipboardList
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { LockBanner } from "@/components/ui/lock-banner";
import { PostConfirmDialog } from "@/components/shared/PostConfirmDialog";
import { PageHeader } from "@/components/shared/PageHeader";
import { Card, CardContent } from "@/components/ui/card";
import { 
 Form, 
 FormControl, 
 FormField, 
 FormItem, 
 FormLabel, 
 FormMessage 
} from "@/components/ui/form";
import { 
 Select, 
 SelectContent, 
 SelectItem, 
 SelectTrigger, 
 SelectValue 
} from "@/components/ui/select";
import { useWarehouses } from "@/features/warehouses/api/useWarehouses";
import { useCreateStocktake } from "@/features/operations/api/useStocktakes";
import { Skeleton } from "@/components/ui/skeleton";
import { PermissionGate } from "@/components/shared/PermissionGate";
import { useWarehouseLock } from "@/hooks/useWarehouseLock";

const buildFormSchema = (t: (k: string) => string) => z.object({
 warehouseId: z.string().min(1, t('validation.warehouse_required')),
 sessionName: z.string().min(3, t('validation.session_name_min')),
 description: z.string().optional(),
});

type StocktakeFormValues = z.infer<ReturnType<typeof buildFormSchema>>;

export function StocktakeForm({ locale }: { locale: 'ar' | 'en' }) {
  const t = useTranslations("operations.stocktake");
  const tc = useTranslations("common");
  const { data: warehouses, isLoading: warehousesLoading } = useWarehouses();
  const createStocktake = useCreateStocktake();

  const [confirmOpen, setConfirmOpen] = useState(false);

  const formSchema = buildFormSchema((k) => t(k as Parameters<typeof t>[0]));

  const form = useForm<StocktakeFormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      warehouseId: "",
      sessionName: "",
      description: "",
    },
  });

  const { router } = useUnsavedChangesGuard(form.formState.isDirty);

 const watchedWarehouse = useWatch({
 control: form.control,
 name: "warehouseId",
 });
 const { data: lockStatus } = useWarehouseLock(watchedWarehouse);
 const isWarehouseLocked = !!lockStatus?.isLocked;

 const onSubmit = (data: StocktakeFormValues) => {
    createStocktake.mutate({
      data: {
        session_name: data.sessionName,
        warehouse_id: data.warehouseId,
        description: data.description,
      },
    }, {
      onSuccess: (session) => {
        router.push(`/stocktake/${session.id}`, { skipGuard: true });
      },
      onError: (error) => {
        console.error("Failed to create stocktake session", error);
      },
    });
  };

 if (warehousesLoading) {
 return (
 <div className="space-y-6 animate-pulse">
 <div className="h-20 bg-surface-container-low rounded-3xl" />
 <div className="h-64 bg-surface-container-low rounded-[2.5rem]" />
 </div>
 );
 }

 return (
 <PermissionGate resource="operations_stocktake" action="create">
 <Form {...form}>
 <form 
 onSubmit={form.handleSubmit(() => setConfirmOpen(true))} 
 className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 max-w-5xl mx-auto"
 >
 <PageHeader 
 title={t('create_new')}
 description={t('new_session_subtitle')}
 actions={
 <Button 
 type="button" 
 variant="ghost" 
 size="sm" 
 onClick={() => router.push('/stocktake')}
 className="text-label-xs font-semibold uppercase text-muted-foreground/60 hover:text-foreground h-10 px-4 rounded-xl"
 >
 <ArrowLeft className={`w-4 h-4 ${locale === 'ar' ? 'rotate-180 ml-2' : 'mr-2'}`} />
 {tc('back')}
 </Button>
 }
 />

 {isWarehouseLocked && (
 <div className="animate-in zoom-in-95 duration-300">
 <LockBanner message={t('warehouse_locked_warning')} />
 </div>
 )}

 <Card className="bg-surface-container-low border-none shadow-2xl shadow-black/5 rounded-[2.5rem] overflow-hidden">
 <CardContent className="p-10 space-y-10">
 {/* Form Header Info */}
 <div className="flex items-center gap-6 pb-8">
 <div className="p-4 rounded-[1.5rem] bg-cyan-600/10 text-cyan-500 border border-cyan-500/20 shadow-[0_0_20px_rgba(8,145,178,0.1)]">
 <Settings2 className="w-8 h-8" />
 </div>
 <div>
 <h3 className="text-title-lg font-bold text-foreground">{t('session_parameters')}</h3>
 <p className="text-label-xs font-semibold text-muted-foreground/40 uppercase mt-1 italic">
 {t('operational_audit_config')}
 </p>
 </div>
 </div>

 <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
 <FormField
 control={form.control}
 name="warehouseId"
 render={({ field }) => (
 <FormItem className="space-y-4">
 <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/40 flex items-center gap-2 px-1">
 <Warehouse className="w-3.5 h-3.5" />
 {tc('warehouse')}
 </FormLabel>
 <Select onValueChange={field.onChange} value={field.value}>
 <FormControl>
 <SelectTrigger className="bg-surface-container-high/30 border-none h-14 px-6 text-label-xs font-bold rounded-2xl shadow-inner shadow-black/5 focus:ring-2 focus:ring-cyan-500/20 transition-all">
 <SelectValue placeholder={t('select_warehouse')} />
 </SelectTrigger>
 </FormControl>
 <SelectContent className="bg-surface-container-highest border border-surface-container-high/50 shadow-2xl rounded-2xl overflow-hidden">
 {warehouses?.map((wh) => (
 <SelectItem key={wh.id} value={wh.id} className="text-label-xs font-bold py-3">
                  {locale === 'ar' ? wh.name_ar : wh.name_en}
 </SelectItem>
 ))}
 </SelectContent>
 </Select>
 <FormMessage className="text-label-xxs font-semibold uppercase px-1" />
 </FormItem>
 )}
 />

 <FormField
 control={form.control}
 name="sessionName"
 render={({ field }) => (
 <FormItem className="space-y-4">
 <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/40 flex items-center gap-2 px-1">
 <ClipboardList className="w-3.5 h-3.5" />
 {t('session_name_label')}
 </FormLabel>
 <FormControl>
 <Input 
 placeholder={t('session_name_placeholder')} 
 className="bg-surface-container-high/30 border-none h-14 px-6 text-label-xs font-bold rounded-2xl shadow-inner shadow-black/5 focus:ring-2 focus:ring-cyan-500/20 transition-all" 
 {...field} 
 />
 </FormControl>
 <FormMessage className="text-label-xxs font-semibold uppercase px-1" />
 </FormItem>
 )}
 />

 <FormField
 control={form.control}
 name="description"
 render={({ field }) => (
 <FormItem className="md:col-span-2 space-y-4">
 <FormLabel className="text-label-xs font-semibold uppercase text-muted-foreground/40 flex items-center gap-2 px-1">
 <FileText className="w-3.5 h-3.5" />
 {t('description_label')}
 </FormLabel>
 <FormControl>
 <Textarea 
 placeholder={t('description_placeholder')} 
 className="bg-surface-container-high/30 border-none min-h-[120px] p-6 text-label-xs font-bold rounded-2xl shadow-inner shadow-black/5 focus:ring-2 focus:ring-cyan-500/20 transition-all resize-none" 
 {...field} 
 />
 </FormControl>
 <FormMessage className="text-label-xxs font-semibold uppercase px-1" />
 </FormItem>
 )}
 />
 </div>
 </CardContent>

 {/* Submission Area */}
 <div className="p-10 bg-surface-container-medium/30 flex flex-col md:flex-row items-center justify-between gap-6">
 <div className="flex items-center gap-4">
 <div className="w-2 h-2 rounded-full bg-cyan-500 animate-pulse" />
 <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase">
 {t('ready_to_initialize')}
 </p>
 </div>
 
 <div className="flex items-center gap-4 w-full md:w-auto">
 <Button 
 type="button" 
 variant="ghost" 
 onClick={() => router.push('/stocktake')} 
 className="flex-1 md:flex-none h-14 px-8 text-label-xs font-semibold uppercase text-muted-foreground/60 hover:text-foreground rounded-2xl"
 >
 {tc('cancel')}
 </Button>
 <Button
 type="submit"
 disabled={createStocktake.isPending || isWarehouseLocked}
 className="flex-1 md:flex-none h-14 px-12 bg-cyan-600 hover:bg-cyan-500 text-white text-label-xs font-semibold uppercase rounded-[1.5rem] transition-all shadow-[0_0_25px_rgba(6,182,212,0.3)] hover:shadow-[0_0_40px_rgba(6,182,212,0.5)] disabled:opacity-30 disabled:grayscale group"
 >
 {createStocktake.isPending ? tc('saving') : (
 <>
 {t('initialize_session')}
 <ChevronRight className={`ms-2 w-4 h-4 transition-transform group-hover:translate-x-1 ${locale === 'ar' ? 'rotate-180' : ''}`} />
 </>
 )}
 </Button>
 </div>
 </div>
 </Card>
 </form>

  <PostConfirmDialog
    open={confirmOpen}
    onOpenChange={setConfirmOpen}
    onConfirm={() => {
      setConfirmOpen(false);
      form.handleSubmit(onSubmit)();
    }}
    title={t('create_confirm_title')}
    description={t('create_confirm_desc')}
    confirmText={tc('confirm')}
    icon="info"
  />
 </Form>
 </PermissionGate>
 );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations, useLocale } from 'next-intl';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ActionMenu } from '@/components/shared/DataTable/ActionMenu';
import { ColumnDef } from '@tanstack/react-table';
import { useTransferList, TransferSummary } from '@/features/operations/hooks/useTransferList';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { MetricCard } from '@/components/ui/metric-card';
import { EmptyState } from '@/components/shared/EmptyState';
import { Button } from '@/components/ui/button';
import { Repeat, Truck, CheckCircle, Plus, Filter } from 'lucide-react';
import { PageHeader } from '@/components/shared/PageHeader';
import { ClientOnlyTime } from '@/components/shared/ClientOnlyTime';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { isTransferInTransit, isTransferPosted } from '@/domain/status-guards';
import { getStatusConfig } from '@/domain/status-ui-map';
import { TRANSFER_STATUS } from '@/contracts/statuses';

export function TransferListClient() {
  const t = useTranslations('operations.transfer');
  const tCommon = useTranslations('common');
  const locale = useLocale() as 'ar' | 'en';
  const router = useRouter();

  const [page, setPage] = useState(1);
  const [status, setStatus] = useState<string>('');

  const { data, isLoading } = useTransferList({ status, page });

  const columns = useMemo<ColumnDef<TransferSummary>[]>(() => [
    {
      accessorKey: 'transfer_status',
      header: tCommon('status_label'),
      cell: ({ row }) => <StatusBadge status={row.original.transfer_status} />,
    },
    {
      accessorKey: 'document_number',
      header: tCommon('doc_number'),
      cell: ({ row }) => (
        <span dir="ltr" className="font-mono text-cyan-500/90 font-semibold text-body-md">
          {row.original.document_number}
        </span>
      ),
    },
    {
      accessorKey: 'from_warehouse_id',
      header: t('from_warehouse'),
      cell: ({ row }) => (
        <span className="opacity-80 font-medium">
          {tCommon('warehouses.' + row.original.from_warehouse_id.toLowerCase())}
        </span>
      ),
    },
    {
      accessorKey: 'to_warehouse_id',
      header: t('to_warehouse'),
      cell: ({ row }) => (
        <span className="opacity-80 font-medium">
          {tCommon('warehouses.' + row.original.to_warehouse_id.toLowerCase())}
        </span>
      ),
    },
    {
      accessorKey: 'shipped_at',
      header: t('shipped_at'),
      cell: ({ row }) => (
        <ClientOnlyTime
          date={row.original.shipped_at}
          mode="date"
          locale={locale}
          className="text-label-xs opacity-60 font-mono font-medium"
        />
      ),
    },
    {
      accessorKey: 'created_at',
      header: tCommon('created_at'),
      cell: ({ row }) => (
        <ClientOnlyTime
          date={row.original.created_at}
          mode="date"
          locale={locale}
          className="text-label-xs opacity-60 font-mono font-medium"
        />
      ),
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end">
          <ActionMenu
            resource="transfer"
            viewUrl={`/transfers/${row.original.id}`}
            editUrl={`/transfers/${row.original.id}/edit`}
            onDelete={() => {
              // TODO: Implement actual delete logic if needed
              console.log('Delete Transfer', row.original.id);
            }}
          />
        </div>
      ),
    },
  ], [t, tCommon, locale]);

  const totalTransfersCount = data?.meta?.total || 0;
  const inTransitCount = data?.data?.filter(i => isTransferInTransit(i.transfer_status)).length || 0;
  const completedCount = data?.data?.filter(i => isTransferPosted(i.transfer_status)).length || 0;

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <Breadcrumb
        items={[
          { label: tCommon('modules.operations'), href: `/transfers` },
          { label: t('title') }
        ]}
      />

      <PageHeader
        title={t('title')}
        description={t('description')}
        actions={
          <div className="flex items-center gap-6">
            <div className="flex flex-col items-end gap-1 border-e border-outline-low pe-6 hidden md:flex">
              <div className="text-label-xs font-semibold uppercase text-muted-foreground/60 flex items-center gap-2">
                <span className="w-1.5 h-1.5 rounded-full bg-cyan-500 animate-pulse shadow-[0_0_8px_rgba(0,229,255,0.8)]" />
                {tCommon('statuses.live_updates')}
              </div>
              <div className="text-label-xxs font-semibold text-muted-foreground/40 whitespace-nowrap" dir="ltr">
                {tCommon('statuses.last_sync')}: <ClientOnlyTime locale={locale} fallback="..." />
              </div>
            </div>
            <PermissionGate action="create" resource="transfer">
              <Link href="/transfers/new">
                <Button className="h-11 px-8 bg-cyan-600 hover:bg-cyan-500 text-white text-label-xs font-semibold uppercase rounded-md transition-all shadow-lg shadow-cyan-900/10 whitespace-nowrap">
                  <Plus className="w-3.5 h-3.5 me-2" />
                  {t('create_new')}
                </Button>
              </Link>
            </PermissionGate>
          </div>
        }
      />

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={t('total_transfers')}
          value={totalTransfersCount}
          icon={Repeat}
          trend="active"
        />
        <MetricCard
          label={tCommon('statuses.in_transit')}
          value={inTransitCount}
          icon={Truck}
          trend="active"
          color="amber"
        />
        <MetricCard
          label={t('completed')}
          value={completedCount}
          icon={CheckCircle}
          trend="active"
          color="emerald"
        />
      </div>

      <div className="bg-surface-container-lowest rounded-lg border border-outline-low/5 overflow-hidden shadow-sm">
        <DataTable
          columns={columns}
          data={data?.data || []}
          isLoading={isLoading}
          onRowClick={(row: TransferSummary) => router.push(`/transfers/${row.id}`)}
          collectionName="operations_transfers"
          enableVirtualization={true}
          containerHeight="600px"
          emptyState={
            <EmptyState
              variant="minimal"
              title={tCommon('datatable.no_records')}

            />
          }
          pagination={data?.meta ? {
            page: page,
            pageSize: 10,
            total: data.meta.total,
            totalPages: data.meta.total_pages,
            onPageChange: setPage
          } : undefined}
          filters={
            <div className="flex items-center gap-6 w-full py-6 px-8 bg-surface-container-low/50 border border-outline-low/10 rounded-xl ambient-shadow backdrop-blur-sm overflow-x-auto no-scrollbar">
              <div className="flex flex-col gap-2 min-w-[240px] flex-1">
                <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{tCommon('status_label')}</label>
                <Select
                  value={status || 'ALL'} onValueChange={(val) => { setStatus(val === 'ALL' ? '' : (val ?? '')); setPage(1); }}
                >
                  <SelectTrigger className="w-full bg-surface-container-highest/40 border-none h-12 px-4 text-label-sm font-semibold rounded-md transition-all hover:bg-surface-container-highest/60 focus:ring-1 focus:ring-cyan-500/10 shadow-inner shadow-black/5">
                    <SelectValue placeholder={tCommon('statuses.all')} />
                  </SelectTrigger>
                  <SelectContent className="bg-surface-container-highest border-outline-low/10 rounded-md">
                    <SelectItem value="ALL">{tCommon('statuses.all')}</SelectItem>
                    {Object.entries(TRANSFER_STATUS).map(([key, value]) => (
                      <SelectItem key={value} value={value}>
                        {tCommon(getStatusConfig(value).labelKey)}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="flex flex-col gap-2 min-w-[300px] flex-[2]">
                <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ms-1">{tCommon('search')}</label>
                <div className="relative group">
                  <Input
                    placeholder={t('search_placeholder')}
                    className="w-full bg-surface-container-highest/40 border-none h-12 ps-12 pe-4 text-label-sm font-semibold rounded-md transition-all group-hover:bg-surface-container-highest/60 focus:ring-1 focus:ring-cyan-500/10 shadow-inner shadow-black/5"
                  />
                  <svg className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40 transition-colors group-hover:text-cyan-500/60" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
              </div>

              <Button className="h-12 px-8 bg-surface-container-highest/30 hover:bg-surface-container-highest/50 text-foreground text-label-xs font-semibold uppercase rounded-md transition-all border border-outline-low/10 shadow-sm group">
                <Filter className="w-3.5 h-3.5 me-2 transition-transform group-hover:rotate-180" />
                {tCommon('filters')}
              </Button>
            </div>
          }
        />
      </div>
    </div>
  );
}

"use client";

import { useTranslations } from 'next-intl';
import { useTransfer } from '@/features/operations/hooks/useTransfer';
import { isDocumentLocked, type DocumentStatus } from '@/core/workflow/document-engine';
import { TransferForm } from '@/features/operations/components/transfer-form';
import { TransferViewer } from '@/features/operations/components/transfer-viewer';
import { TRANSFER_STATUS } from '@/contracts/statuses';

import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';

import { PageSkeleton } from '@/components/shared/PageSkeleton';

export function TransferDetailClient({ id }: { id: string }) {
  const t = useTranslations('operations.transfer');
  const { data: transfer, isLoading } = useTransfer(id);
  const conflict = useConflictHandler('transfer', id);

  if (isLoading) return <PageSkeleton variant="detail" />;

  const transferStatus = transfer?.transfer_status ?? TRANSFER_STATUS.DRAFT;
  const isDocLocked = isDocumentLocked("TRANSFER", transferStatus as DocumentStatus);

  if (isDocLocked && transfer) {
    return <TransferViewer transfer={transfer} />;
  }

  if (!transfer) return null;

  return (
    <>
      <TransferForm 
        transfer={transfer} 
        id={id} 
        onConflict={conflict.triggerConflict}
      />
      <ConflictDialog 
        open={conflict.open}
        onClose={conflict.handleClose}
        onReload={conflict.handleReload}
      />
    </>
  );
}

'use client';

import { useState, useMemo, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Button } from '@/components/ui/button';
import { DocumentLineItemTable } from '@/components/shared/DocumentLineItemTable/DocumentLineItemTable';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { DocumentLockBanner, DocumentLockWrapper } from '@/components/shared/DocumentLockBanner';
import { FormFooter } from '@/components/shared/FormFooter';
import { useTransfer, TransferLine } from '@/features/operations/hooks/useTransfer';
import { useReceiveTransfer } from '@/features/operations/hooks/useReceiveTransfer';
import { useWarehouseLock } from '@/hooks/useWarehouseLock';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { PackageCheck, ArrowLeft, AlertCircle, Info } from 'lucide-react';
import { ScanInput } from '@/components/shared/ScanInput/ScanInput';
import { cn } from '@/lib/utils';
import { canPerformActionV2, type DocumentStatus } from '@/core/workflow/document-engine';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';
import { useAuth } from '@/providers/AuthProvider';

import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';

export function TransferReceiveClient({ id, locale }: { id: string; locale: 'ar' | 'en' }) {
  const t = useTranslations('operations.transfer');
  const tCommon = useTranslations('common');

  const { data: transfer, isLoading, error } = useTransfer(id);
  const { user } = useAuth();
  const { open, handleReload, handleClose, triggerConflict } = useConflictHandler('transfer', id);
  const receiveTransfer = useReceiveTransfer(id, { onConflict: triggerConflict });

  const [lines, setLines] = useState<(TransferLine & { _receivedQty?: number })[]>([]);
  const [varianceReason, setVarianceReason] = useState('');
  const [confirmDialogOpen, setConfirmDialogOpen] = useState(false);
  const [scanStatus, setScanStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [statusMessage, setStatusMessage] = useState('');

  const { data: fromLockState } = useWarehouseLock(transfer?.from_warehouse_id ?? '');
  const { data: toLockState } = useWarehouseLock(transfer?.to_warehouse_id ?? '');
  const isEitherLocked = (fromLockState?.isLocked || toLockState?.isLocked) ?? false;

  const [prevTransferId, setPrevTransferId] = useState<string | null>(null);
  
  if (transfer && transfer.id !== prevTransferId) {
    setPrevTransferId(transfer.id);
    setLines(transfer.lines.map(l => ({ 
      ...l, 
      _receivedQty: l.shipped_qty ?? l.qty 
    })));
  }

  const hasVariance = lines.some(l => (l._receivedQty ?? 0) !== (l.shipped_qty ?? l.qty));
  const isVarianceValid = !hasVariance || varianceReason.trim().length >= 15;

  const isDirty = useMemo(() => {
    if (!transfer) return false;
    const initialReason = '';
    const reasonChanged = varianceReason !== initialReason;
    
    const linesChanged = lines.some((l) => {
      const originalLine = transfer.lines.find(ol => ol.id === l.id);
      if (!originalLine) return false;
      const initialQty = originalLine.shipped_qty ?? originalLine.qty;
      return l._receivedQty !== initialQty;
    });
    
    return reasonChanged || linesChanged;
  }, [varianceReason, lines, transfer]);

  const { router, registerDirty } = useUnsavedChangesGuard(isDirty);

  const handleReceive = () => {
    if (!transfer) return;
    const receiveLines = lines.map(l => ({
      line_id: l.id,
      received_qty: l._receivedQty ?? l.qty
    }));
    
    receiveTransfer.mutate({
      body: {
        version: transfer.version ?? 0,
        lines: receiveLines,
        confirmation: 'ACKNOWLEDGE_IRREVERSIBLE',
        variance_reason: hasVariance ? varianceReason : undefined
      }
    }, {
      onSuccess: () => {
        router.push(`/transfers/${id}`, { skipGuard: true });
      }
    });
  };

  if (isLoading) return <PageSkeleton />;
  if (error || !transfer) return <ErrorState onRetry={() => window.location.reload()} />;

  if (!canPerformActionV2('TRANSFER', transfer?.transfer_status as DocumentStatus, 'RECEIVE', user?.role)) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-4">
        <AlertCircle className="w-12 h-12 text-status-error" />
        <p className="font-bold text-title-sm">{t('invalid_status_for_receive')}</p>
        <Button onClick={() => router.push(`/transfers/${id}`)} variant="outline">
          {tCommon('back')}
        </Button>
      </div>
    );
  }

  return (
    <form 
      onSubmit={(e) => {
        e.preventDefault();
        setConfirmDialogOpen(true);
      }}
      className="p-8 max-w-[1200px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-32"
    >
      <div className="flex items-center justify-between">
        <Breadcrumb 
          items={[
            { label: t('title'), href: `/transfers` },
            { label: transfer.document_number, href: `/transfers/${id}` },
            { label: t('receive') }
          ]} 
        />
        <Button
          type="button"
          variant="ghost"
          onClick={() => router.push(`/transfers/${id}`)}
          className="text-label-xs font-semibold uppercase text-muted-foreground hover:text-foreground"
        >
          <ArrowLeft className="w-3 h-3 me-2" />
          {tCommon('back')}
        </Button>
      </div>

      <PageHeader
        title={t('confirm_receipt')}
        description={t('receive_confirm_desc')}
      />

      <div className="space-y-4">
        <DocumentLockBanner 
          isLocked={true}
          status={transfer.transfer_status as DocumentStatus}
        />
        
        {hasVariance && (
          <div className="bg-status-warning/10 border border-status-warning/30 rounded-2xl p-4 flex items-start gap-4 animate-in slide-in-from-top-2 duration-500">
            <Info className="w-5 h-5 text-status-warning mt-0.5" />
            <div className="space-y-1">
              <p className="text-label-sm font-semibold text-status-warning uppercase">{t('variance_detected')}</p>
              <p className="text-body-md text-status-warning/80 font-medium">{t('variance_instruction')}</p>
            </div>
          </div>
        )}
      </div>

      <DocumentLockWrapper isLocked={false}>
        <div className="space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="bg-surface-container-low/50 rounded-3xl border border-white/5 p-8 space-y-6 relative overflow-hidden h-full">
              <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-r from-emerald-500/50 to-transparent" />
              <div className="flex justify-between items-start">
                <div className="space-y-1">
                  <span className="text-label-xs font-semibold uppercase text-muted-foreground/50">{t('destination')}</span>
                  <p className="text-title-lg font-semibold">{transfer.to_warehouse_name}</p>
                </div>
                <div className="bg-emerald-500/10 p-3 rounded-2xl">
                  <PackageCheck className="w-6 h-6 text-emerald-500" />
                </div>
              </div>

              <div className="pt-4 border-t border-white/5 space-y-4">
                <div className="space-y-2">
                  <label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{tCommon('notes')}</label>
                  <p className="text-body-md font-medium text-foreground/80 leading-relaxed bg-surface-container-highest/20 p-3 rounded-xl border border-white/5">
                    {transfer.notes || '—'}
                  </p>
                </div>
              </div>
            </div>

            <div className={cn(
              "bg-surface-container-low/50 rounded-3xl border p-8 space-y-4 transition-all duration-500",
              hasVariance ? 'border-status-warning/40 shadow-xl shadow-status-warning/5' : 'border-white/5'
            )}>
              <div className="flex items-center justify-between">
                <label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t('variance_reason')}</label>
                {hasVariance && (
                  <span className={cn(
                    "text-label-xxs font-bold px-2 py-0.5 rounded-full",
                    varianceReason.trim().length >= 15 
                      ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' 
                      : 'bg-status-error/10 text-status-error border border-status-error/20'
                  )}>
                    {varianceReason.trim().length}/15
                  </span>
                )}
              </div>
              <textarea
                value={varianceReason}
                onChange={e => setVarianceReason(e.target.value)}
                disabled={!hasVariance}
                placeholder={t('variance_reason_placeholder')}
                className={cn(
                  "w-full bg-surface-container-highest/40 border rounded-2xl p-4 font-medium text-body-md focus:ring-2 transition-all outline-none resize-none min-h-[140px]",
                  hasVariance 
                    ? 'border-status-warning/20 focus:ring-status-warning/30 hover:bg-surface-container-highest/60' 
                    : 'border-white/5 opacity-40 cursor-not-allowed'
                )}
              />
              {!isVarianceValid && hasVariance && (
                <p className="text-label-xs font-bold text-status-error animate-pulse flex items-center gap-1">
                  <AlertCircle className="w-3 h-3" />
                  {t('variance_required_error')}
                </p>
              )}
            </div>
          </div>

          <div className="bg-surface-container-low/30 rounded-3xl border border-white/5 overflow-hidden shadow-2xl">
            <div className="p-6 border-b border-white/5 flex items-center justify-between bg-surface-container-low">
              <div className="flex items-center gap-4">
                <h3 className="text-label-xs font-semibold uppercase text-emerald-500">{t('items_to_receive')}</h3>
                <div className="h-4 w-px bg-white/10" />
                <span className="text-label-xs font-bold text-muted-foreground/60">{lines.length} {tCommon('items')}</span>
              </div>
              <div className="flex items-center gap-2 px-3 py-1 bg-emerald-500/10 rounded-full border border-emerald-500/20">
                <div className="w-1 h-1 rounded-full bg-emerald-500 animate-pulse" />
                <span className="text-label-xxs font-semibold uppercase text-emerald-500">{t('scan_mode')}</span>
              </div>
            </div>

            <div className="p-6 bg-surface-container-low/50 border-b border-white/5">
              <ScanInput
                onScan={(barcode) => {
                  const lineIndex = lines.findIndex(l => l.item?.code === barcode);
                  if (lineIndex !== -1) {
                    setLines(prev => prev.map((l, i) => 
                      i === lineIndex ? { ...l, _receivedQty: (l._receivedQty ?? 0) + 1 } : l
                    ));
                    setScanStatus('success');
                    setStatusMessage(`${t('scan_success')}: ${locale === 'ar' ? lines[lineIndex].item?.name_ar : lines[lineIndex].item?.name_en}`);
                    setTimeout(() => setScanStatus('idle'), 2000);
                  } else {
                    setScanStatus('error');
                    setStatusMessage(t('scan_error'));
                    setTimeout(() => setScanStatus('idle'), 2000);
                  }
                }}
                placeholder={t('scan_placeholder_receive')}
                scanStatus={scanStatus}
                statusMessage={statusMessage}
                scannerMode={true}
                className="max-w-md mx-auto"
              />
            </div>

            <DocumentLineItemTable
              lines={lines}
              locale={locale}
              isReadOnly={false}
              onRemoveLine={() => {}}
              hideLotColumns={true}
              headers={{
                code: tCommon('table_headers.code'),
                name: tCommon('table_headers.name'),
                qty: t('transfer_qty'),
                uom: tCommon('table_headers.uom'),
              }}
              extraColumns={[
                {
                  header: t('shipped_qty'),
                  cell: (line: TransferLine & { _receivedQty?: number }) => (
                    <div className="flex justify-center">
                      <span dir="ltr" className="font-mono text-body-md font-semibold bg-surface-container-highest px-3 py-1 rounded-lg border border-white/5">
                        {line.shipped_qty ?? line.qty}
                      </span>
                    </div>
                  ),
                },
                {
                  header: t('received_qty'),
                  cell: (line: TransferLine & { _receivedQty?: number }) => (
                    <div className="flex justify-center">
                      <input
                        type="number"
                        dir="ltr"
                        className={cn(
                          "w-24 bg-surface-container-highest border rounded-lg text-center px-2 py-2 font-mono font-bold focus:ring-2 outline-none transition-all",
                          (line._receivedQty ?? 0) !== (line.shipped_qty ?? line.qty) 
                            ? 'text-status-warning border-status-warning/40 focus:ring-status-warning/30 shadow-[0_0_15px_rgba(255,152,0,0.1)]' 
                            : 'text-emerald-500 border-emerald-500/20 focus:ring-emerald-500/30'
                        )}
                        value={line._receivedQty ?? line.qty}
                        onChange={e => {
                          const val = Number(e.target.value);
                          setLines(prev =>
                            prev.map(l => l.id === line.id ? { ...l, _receivedQty: val } : l)
                          );
                        }}
                      />
                    </div>
                  ),
                },
              ]}
            />
          </div>
        </div>
      </DocumentLockWrapper>

      <FormFooter
        onCancel={() => router.push(`/transfers/${id}`, { skipGuard: true })}
        actions={
          <PermissionGate action="post" resource="transfer">
            <Button
              type="submit"
              disabled={isEitherLocked || receiveTransfer.isPending || !isVarianceValid}
              className="bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl h-14 px-12 text-label-xs font-black uppercase tracking-widest transition-all shadow-2xl shadow-emerald-600/30 border-none min-w-[240px]"
            >
              <PackageCheck className="w-5 h-5 me-3" />
              {t('complete_receive')}
            </Button>
          </PermissionGate>
        }
      />

      <PostConfirmDialog
        open={confirmDialogOpen}
        onOpenChange={setConfirmDialogOpen}
        title={t('receive_confirm_title')}
        description={t('receive_confirm_desc')}
        warningText={t('receive_confirm_warning')}
        requiresTextConfirmation={true}
        onConfirm={handleReceive}
        isLoading={receiveTransfer.isPending}
      />

      <ConflictDialog 
        open={open}
        onReload={handleReload}
        onClose={handleClose}
      />
    </form>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { useRouter } from '@/i18n/navigation';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Button } from '@/components/ui/button';
import { DocumentLineItemTable } from '@/components/shared/DocumentLineItemTable/DocumentLineItemTable';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { LockBanner } from '@/components/shared/LockBanner';
import { ScanInput } from '@/components/shared/ScanInput/ScanInput';
import { useTransfer, TransferLine } from '@/features/operations/hooks/useTransfer';
import { useShipTransfer } from '@/features/operations/hooks/useShipTransfer';
import { useWarehouseLock } from '@/hooks/useWarehouseLock';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { cn } from '@/lib/utils';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { isDocumentLocked, canPerformActionV2, type DocumentStatus } from '@/core/workflow/document-engine';
import { useAuth } from '@/providers/AuthProvider';
import { AlertCircle, Truck, ArrowLeft, Printer } from 'lucide-react';
import { DocumentLockBanner, DocumentLockWrapper } from '@/components/shared/DocumentLockBanner';
import { FormFooter } from '@/components/shared/FormFooter';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';

export function TransferShipClient({ id, locale }: { id: string; locale: 'ar' | 'en' }) {
  const t = useTranslations('operations.transfer');
  const tCommon = useTranslations('common');
  const { data: transfer, isLoading } = useTransfer(id);
  const { user } = useAuth();
  const shipTransfer = useShipTransfer();

  const [scannedLines, setScannedLines] = useState<Record<string, number>>({});
  const [confirmDialogOpen, setConfirmDialogOpen] = useState(false);
  const [scanStatus, setScanStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [statusMessage, setStatusMessage] = useState('');

  const isDirty = Object.keys(scannedLines).length > 0;
  const { router } = useUnsavedChangesGuard(isDirty);

  const { data: fromLockState } = useWarehouseLock(transfer?.from_warehouse_id ?? '');
  const { data: toLockState } = useWarehouseLock(transfer?.to_warehouse_id ?? '');
  const isEitherLocked = (fromLockState?.isLocked || toLockState?.isLocked) ?? false;

  const handleScan = useCallback((barcode: string) => {
    const line = transfer?.lines.find(l => l.item?.code === barcode);
    if (line) {
      setScannedLines(prev => ({
        ...prev,
        [line.id]: (prev[line.id] ?? 0) + 1
      }));
      setScanStatus('success');
      setStatusMessage(`${t('scan_success')}: ${locale === 'ar' ? line.item?.name_ar : line.item?.name_en}`);
      setTimeout(() => setScanStatus('idle'), 2000);
    } else {
      setScanStatus('error');
      setStatusMessage(t('scan_error'));
      setTimeout(() => setScanStatus('idle'), 2000);
    }
  }, [transfer, t, locale]);

  const handleShip = () => {
    if (!transfer) return;
    shipTransfer.mutate(
      { id, version: transfer.version || 1 },
      {
        onSuccess: () => {
          router.push(`/transfers/${id}`, { skipGuard: true });
        },
      }
    );
  };

  if (isLoading || !transfer) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-6">
        <div className="relative w-24 h-24 flex items-center justify-center text-cyan-500">
          <Truck className="w-12 h-12 animate-bounce" />
        </div>
      </div>
    );
  }

  if (!canPerformActionV2('TRANSFER', transfer?.transfer_status as DocumentStatus, 'SHIP', user?.role)) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-4">
        <AlertCircle className="w-12 h-12 text-status-error" />
        <p className="font-bold text-title-sm">{t('invalid_status_for_ship')}</p>
        <Button onClick={() => router.push(`/transfers/${id}`)} variant="outline">
          {tCommon('back')}
        </Button>
      </div>
    );
  }

  const allScanned = transfer.lines.every(l => (scannedLines[l.id] ?? 0) >= l.qty);

  return (
    <div className="p-8 max-w-[1200px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex items-center justify-between">
        <Breadcrumb 
          items={[
            { label: t('title'), href: `/transfers` },
            { label: transfer.document_number, href: `/transfers/${id}` },
            { label: t('ship') }
          ]} 
        />
        <Button
          variant="ghost"
          onClick={() => router.push(`/transfers/${id}`)}
          className="text-label-xs font-semibold uppercase text-muted-foreground hover:text-foreground"
        >
          <ArrowLeft className="w-3 h-3 me-2" />
          {tCommon('back')}
        </Button>
      </div>

      <PageHeader
        title={t('ship_transfer')}
        description={t('ship_confirm_desc')}
        actions={
          <PermissionGate action="post" resource="transfer">
            <Button
              variant="outline"
              className="bg-surface-container-high border-white/5 rounded-xl h-11 px-6 text-label-xs font-semibold uppercase transition-all hover:bg-surface-container-highest"
              onClick={() => window.print()}
            >
              <Printer className="w-4 h-4 me-2" />
              {tCommon('print')}
            </Button>
          </PermissionGate>
        }
      />

      <form 
        onSubmit={(e) => e.preventDefault()} 
        className="space-y-8"
      >
        <DocumentLockBanner 
          status={transfer.transfer_status} 
          isLocked={false} 
        />

        <DocumentLockWrapper isLocked={false}>
          <div className="space-y-4">
            {fromLockState?.isLocked && <LockBanner lockState={fromLockState} />}
            {toLockState?.isLocked && toLockState.sessionId !== fromLockState?.sessionId && (
              <LockBanner lockState={toLockState} />
            )}
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-1">
              <div className="bg-surface-container-low/50 rounded-3xl border border-white/5 p-8 space-y-8 relative overflow-hidden h-full">
                <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-r from-cyan-500/50 to-transparent" />
                
                <div className="space-y-6">
                  <div className="space-y-1">
                    <span className="text-label-xs font-semibold uppercase text-muted-foreground/50">{t('from_warehouse')}</span>
                    <p className="text-title-lg font-semibold">{transfer.from_warehouse_name}</p>
                  </div>

                  <div className="space-y-1">
                    <span className="text-label-xs font-semibold uppercase text-muted-foreground/50">{t('to_warehouse')}</span>
                    <p className="text-title-lg font-semibold">{transfer.to_warehouse_name}</p>
                  </div>

                  <div className="pt-6 border-t border-white/5">
                    <ScanInput
                      onScan={handleScan}
                      placeholder={t('scan_placeholder_ship')}
                      scanStatus={scanStatus}
                      statusMessage={statusMessage}
                      scannerMode={true}
                      className="w-full"
                    />
                  </div>
                </div>
              </div>
            </div>

            <div className="lg:col-span-2">
              <div className="bg-surface-container-low/30 rounded-3xl border border-white/5 overflow-hidden shadow-2xl h-full">
                <div className="p-6 border-b border-white/5 flex items-center justify-between bg-surface-container-low">
                  <h3 className="text-label-xs font-semibold uppercase text-cyan-500">{t('manifest_items')}</h3>
                  <div className="flex items-center gap-2 px-3 py-1 bg-cyan-500/10 rounded-full border border-cyan-500/20">
                    <div className={cn("w-1.5 h-1.5 rounded-full animate-pulse", allScanned ? "bg-emerald-500" : "bg-cyan-500")} />
                    <span className={cn("text-label-xxs font-semibold uppercase tracking-normal", allScanned ? "text-emerald-500" : "text-cyan-500")}>
                      {allScanned ? tCommon('statuses.completed') : t('verification_in_progress')}
                    </span>
                  </div>
                </div>
                
                <DocumentLineItemTable
                  lines={transfer.lines}
                  locale={locale}
                  isReadOnly={true}
                  onRemoveLine={() => {}}
                  hideLotColumns={true}
                  headers={{
                    code: tCommon('table_headers.code'),
                    name: tCommon('table_headers.name'),
                    qty: t('transfer_qty'),
                    uom: tCommon('table_headers.uom'),
                  }}
                  extraColumns={[
                    {
                      header: tCommon('status'),
                      cell: (line: TransferLine) => {
                        const scanned = scannedLines[line.id] ?? 0;
                        const isFullyScanned = scanned >= line.qty;
                        return (
                          <div className="flex justify-center">
                            <div className={cn(
                              "px-3 py-1 rounded-lg text-label-xs font-semibold uppercase flex items-center gap-2",
                              isFullyScanned 
                              ? "bg-emerald-500/10 text-emerald-500 border border-emerald-500/20" 
                              : scanned > 0 
                              ? "bg-cyan-500/10 text-cyan-500 border border-cyan-500/20"
                              : "bg-surface-container-highest text-muted-foreground/40 border border-white/5"
                            )}>
                              {isFullyScanned ? `✓ ${t('verified_label')}` : `${scanned}/${line.qty}`}
                            </div>
                          </div>
                        );
                      }
                    }
                  ]}
                />
              </div>
            </div>
          </div>
        </DocumentLockWrapper>

        <FormFooter 
          onCancel={() => router.push(`/transfers/${id}`, { skipGuard: true })}
          onSubmit={handleShip}
          isSaving={shipTransfer.isPending}
          isLocked={false}
          isDirty={isDirty}
          isValid={allScanned}
          actions={
            <PermissionGate action="post" resource="transfer">
              <Button
                disabled={isEitherLocked || shipTransfer.isPending}
                onClick={() => setConfirmDialogOpen(true)}
                className="bg-cyan-600 hover:bg-cyan-500 text-white rounded-2xl h-14 px-12 text-label-xs font-black uppercase tracking-widest transition-all shadow-2xl shadow-cyan-600/30 border-none"
              >
                <Truck className="w-5 h-5 me-3" />
                {t('confirm_shipment')}
              </Button>
            </PermissionGate>
          }
        />

        <PostConfirmDialog
          open={confirmDialogOpen}
          onOpenChange={setConfirmDialogOpen}
          title={t('ship_confirm_title')}
          description={t('ship_confirm_desc')}
          warningText={t('ship_confirm_warning')}
          requiresTextConfirmation={false}
          onConfirm={handleShip}
          isLoading={shipTransfer.isPending}
        />
      </form>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useTranslations } from 'next-intl';

import { useParams } from 'next/navigation';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { Button } from '@/components/ui/button';
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from '@/components/ui/select';
import { useWarehouses } from '@/features/warehouses/api/useWarehouses';
import { useItems } from '@/features/items/api/useItems';
import { useCreateTransfer } from '@/features/operations/hooks/useCreateTransfer';
import { useWarehouseLock } from '@/hooks/useWarehouseLock';
import { LockBanner } from '@/components/shared/LockBanner';
import { DocumentLineItemTable } from '@/components/shared/DocumentLineItemTable/DocumentLineItemTable';
import { ScanInput } from '@/components/shared/ScanInput/ScanInput';
import { FormFooter } from '@/components/shared/FormFooter';

import { Save, Warehouse, PackagePlus } from 'lucide-react';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import { useAbortController } from '@/hooks/useAbortController';

interface NewTransferLine {
  id: string;
  item_id: string;
  item: {
    id: string;
    code: string;
    name_ar: string;
    name_en: string;
    primary_uom: { code: string };
  };
  qty: number;
  uom_id: string;
}

export function TransferNewClient() {
  const params = useParams();
  const locale = (params.locale as 'ar' | 'en') || 'en';
  const t = useTranslations('operations.transfer');
  const tCommon = useTranslations('common');
  const abortController = useAbortController();
  const { data: warehouses, isLoading: isLoadingWarehouses, error: errorWarehouses } = useWarehouses();
  const { data: items, isLoading: isLoadingItems, error: errorItems } = useItems();
  const createTransfer = useCreateTransfer();

  const [fromWarehouseId, setFromWarehouseId] = useState('');
  const [toWarehouseId, setToWarehouseId] = useState('');
  const [notes, setNotes] = useState('');
  const [lines, setLines] = useState<NewTransferLine[]>([]);

  // Unsaved changes guard
  const isDirty = fromWarehouseId !== '' || toWarehouseId !== '' || notes !== '' || lines.length > 0;
  const { router } = useUnsavedChangesGuard(isDirty);

  // Warehouse locks
  const { data: fromLockState } = useWarehouseLock(fromWarehouseId);
  const { data: toLockState } = useWarehouseLock(toWarehouseId);
  const isEitherLocked = !!fromLockState?.isLocked || !!toLockState?.isLocked;

  const handleAddItem = (barcode: string) => {
    const item = items?.find(i => i.barcode === barcode || i.code === barcode);
    if (!item) return;

    setLines(prev => {
      const existing = prev.find(l => l.item_id === item.id);
      if (existing) {
        return prev.map(l => l.item_id === item.id ? { ...l, qty: l.qty + 1 } : l);
      }
      return [...prev, {
        id: `temp-${item.id}-${Date.now()}`,
        item_id: item.id,
        item: {
          id: item.id,
          code: item.code,
          name_ar: item.name_ar,
          name_en: item.name_en,
          primary_uom: { code: item.primary_uom.code }
        },
        qty: 1,
        uom_id: item.primary_uom.id
      }];
    });
  };

  const handleSave = () => {
    if (!fromWarehouseId || !toWarehouseId || lines.length === 0) return;
    
    createTransfer.mutate({
      payload: {
        from_warehouse_id: fromWarehouseId,
        to_warehouse_id: toWarehouseId,
        notes,
        lines: lines.map(l => ({
          item_id: l.item_id,
          qty: l.qty,
          uom_id: l.uom_id
        }))
      },
      signal: abortController.signal
    }, {
      onSuccess: (data) => {
        router.push(`/transfers/${data.id}`, { skipGuard: true });
      }
    });
  };

  const isValid = !!(fromWarehouseId && toWarehouseId && fromWarehouseId !== toWarehouseId && lines.length > 0);

  if (isLoadingWarehouses || isLoadingItems) return <PageSkeleton />;
  if (errorWarehouses || errorItems) return <ErrorState onRetry={() => window.location.reload()} />;

  return (
    <form 
      onSubmit={(e) => {
        e.preventDefault();
        handleSave();
      }}
      className="p-8 max-w-[1600px] mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000 pb-32"
    >
      <Breadcrumb 
        items={[
          { label: tCommon('modules.operations'), href: `/transfers` },
          { label: t('title'), href: `/transfers` },
          { label: t('create_new') }
        ]} 
      />

      <PageHeader
        title={t('create_new')}
        description={t('description')}
      />

      <div className="space-y-2">
        {fromLockState?.isLocked && <LockBanner lockState={fromLockState} />}
        {toLockState?.isLocked && toLockState.sessionId !== fromLockState?.sessionId && (
          <LockBanner lockState={toLockState} />
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-8">
          <div className="bg-surface-container-low/50 p-8 rounded-[2.5rem] border border-white/5 relative overflow-hidden shadow-2xl">
            <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-e from-cyan-500/50 via-cyan-500/20 to-transparent" />
            
            <div className="flex items-center gap-3 mb-6">
              <Warehouse className="w-4 h-4 text-cyan-500" />
              <h3 className="text-label-sm font-semibold uppercase tracking-wider text-foreground/70">
                {t('transfer_parameters')}
              </h3>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-label-sm font-semibold uppercase text-muted-foreground/70 ms-1">
                  {t('from_warehouse')}
                </label>
                <Select
                  value={fromWarehouseId}
                  onValueChange={(val) => setFromWarehouseId(val || '')}
                >
                  <SelectTrigger className="w-full bg-surface-container-highest/40 border-none h-11 px-6 text-label-sm font-bold rounded-2xl shadow-inner shadow-black/5 focus:ring-2 focus:ring-cyan-500/20 transition-all">
                    <SelectValue placeholder={t('select_warehouse')} />
                  </SelectTrigger>
                  <SelectContent className="bg-surface-container-highest border border-surface-container-high/50 shadow-2xl rounded-2xl overflow-hidden">
                    {warehouses?.map((wh) => (
                      <SelectItem key={wh.id} value={wh.id} className="text-label-sm font-bold py-3 focus:bg-cyan-500/10 focus:text-cyan-400">
                        {locale === 'ar' ? wh.name_ar : wh.name_en}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <label className="text-label-sm font-semibold uppercase text-muted-foreground/70 ms-1">
                  {t('to_warehouse')}
                </label>
                <Select
                  value={toWarehouseId}
                  onValueChange={(val) => setToWarehouseId(val || '')}
                >
                  <SelectTrigger className="w-full bg-surface-container-highest/40 border-none h-11 px-6 text-label-sm font-bold rounded-2xl shadow-inner shadow-black/5 focus:ring-2 focus:ring-cyan-500/20 transition-all">
                    <SelectValue placeholder={t('select_warehouse')} />
                  </SelectTrigger>
                  <SelectContent className="bg-surface-container-highest border border-surface-container-high/50 shadow-2xl rounded-2xl overflow-hidden">
                    {warehouses?.map((wh) => (
                      <SelectItem key={wh.id} value={wh.id} className="text-label-sm font-bold py-3 focus:bg-cyan-500/10 focus:text-cyan-400">
                        {locale === 'ar' ? wh.name_ar : wh.name_en}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {fromWarehouseId && toWarehouseId && fromWarehouseId === toWarehouseId && (
                  <p className="text-label-xxs font-bold text-status-error uppercase px-1 mt-1">
                    {t('warehouse_match_error')}
                  </p>
                )}
              </div>

              <div className="space-y-2">
                <label className="text-label-sm font-semibold uppercase text-muted-foreground/70 ms-1">
                  {tCommon('notes')}
                </label>
                <textarea
                  value={notes}
                  onChange={e => setNotes(e.target.value)}
                  placeholder={t('notes_placeholder')}
                  className="w-full bg-surface-container-highest/40 border border-white/5 rounded-2xl p-4 font-medium text-body-md focus:ring-2 focus:ring-cyan-500/30 transition-all outline-none resize-none min-h-[120px] hover:bg-surface-container-highest/60"
                />
              </div>
            </div>
          </div>
        </div>

        <div className="lg:col-span-2 space-y-6">
          <div className="bg-surface-container-low/50 p-8 rounded-[2.5rem] border border-white/5 relative overflow-hidden shadow-2xl">
            <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-e from-emerald-500/50 via-emerald-500/20 to-transparent" />
            
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-3">
                <PackagePlus className="w-5 h-5 text-emerald-500" />
                <h3 className="text-label-sm font-semibold uppercase tracking-wider text-foreground/70">
                  {t('items_to_transfer')}
                </h3>
              </div>
              <div className="flex items-center gap-2 px-4 py-1.5 bg-emerald-500/10 rounded-full border border-emerald-500/20">
                <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                <span className="text-label-xxs font-semibold uppercase text-emerald-500">
                  {lines.length} {tCommon('items')}
                </span>
              </div>
            </div>

            <div className="mb-8">
              <ScanInput 
                onScan={handleAddItem}
                placeholder={t('scan_item_placeholder')} className="max-w-md mx-auto"
              />
            </div>

            <div className="bg-surface-container-low/30 rounded-[2rem] border border-white/5 overflow-hidden">
              <DocumentLineItemTable
                lines={lines}
                locale={locale}
                isReadOnly={false}
                onRemoveLine={(id) => setLines(prev => prev.filter(l => l.id !== id))}
                hideLotColumns={true}
                headers={{
                  code: tCommon('table_headers.code'),
                  name: tCommon('table_headers.name'),
                  qty: tCommon('table_headers.qty'),
                  uom: tCommon('table_headers.uom'),
                }}
                renderQty={(line) => (
                  <div className="flex justify-center">
                    <input
                      type="number"
                      min="0.001"
                      step="0.001"
                      value={line.qty}
                      onChange={(e) => {
                        const val = parseFloat(e.target.value);
                        setLines(prev => prev.map(l => l.id === line.id ? { ...l, qty: val || 0 } : l));
                      }}
                      className="w-24 bg-surface-container-highest/60 border border-white/5 rounded-lg text-center py-1.5 font-mono text-body-md font-semibold focus:ring-2 focus:ring-cyan-500/30 outline-none transition-all hover:bg-surface-container-highest/80"
                    />
                  </div>
                )}
              />
            </div>
          </div>
        </div>
      </div>

      <FormFooter
        onCancel={() => router.push('/transfers', { skipGuard: true })}
        onSubmit={handleSave}
        isSaving={createTransfer.isPending}
        isDirty={isDirty}
        isValid={isValid && !isEitherLocked}
        saveLabel={t('save_transfer')}
      />
    </form>
  );
}

