                className="h-14 px-10 bg-operational-cyan text-white hover:bg-operational-cyan/90 transition-all font-bold uppercase text-[10px] tracking-widest gap-3 rounded-2xl shadow-[0_10px_20px_rgba(var(--operational-cyan-rgb),0.2)] disabled:opacity-50 disabled:shadow-none"
              >
                {isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                {tCommon('save')}
              </Button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect } from 'react';
import Image from 'next/image';
import { useTranslations } from 'next-intl';
import { useForm, useWatch } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { 
 Building2, 
 MapPin, 
 Phone, 
 Mail, 
 FileText, 
 Upload, 
 Save, 
 Image as ImageIcon,
 Loader2,
 Trash2,
 CheckCircle2
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { 
  useRestaurantProfile, 
  useUpdateRestaurantProfile, 
  RestaurantProfileSchema, 
  type RestaurantProfile 
} from '@/features/admin/hooks/useRestaurantProfile';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { cn } from '@/lib/utils';

export function ProfileFormClient({ locale }: { locale: string }) {
 const t = useTranslations('admin.restaurant_profile');
 const tCommon = useTranslations('common');
 const { data: profile, isLoading } = useRestaurantProfile();
 const { mutateAsync: updateProfile, isPending } = useUpdateRestaurantProfile();
 
const { register, handleSubmit, formState: { errors, isDirty }, reset, setValue, control } = useForm<RestaurantProfile>({
  resolver: zodResolver(RestaurantProfileSchema),
  });

  useUnsavedChangesGuard(isDirty);

 const logoPreview = useWatch({ control, name: 'logo' });

 useEffect(() => {
 if (profile) {
 reset(profile);
 }
 }, [profile, reset]);

 const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
 const file = e.target.files?.[0];
 if (file) {
 const reader = new FileReader();
 reader.onloadend = () => {
 const base64 = reader.result as string;
 setValue('logo', base64, { shouldDirty: true });
 };
 reader.readAsDataURL(file);
 }
 };

 const removeLogo = () => {
 setValue('logo', '', { shouldDirty: true });
 };

const onSubmit = async (data: RestaurantProfile) => {
    try {
      await updateProfile({ values: data });
      reset(data);
    } catch {
      // Error handled by mutation hooks
    }
  };

 if (isLoading) {
 return (
 <div className="space-y-8 animate-pulse">
 <div className="h-32 bg-surface-container-highest rounded-[var(--radius)] w-full" />
 <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
 <div className="h-20 bg-surface-container-highest rounded-[var(--radius)] w-full" />
 <div className="h-20 bg-surface-container-highest rounded-[var(--radius)] w-full" />
 </div>
 </div>
 );
 }

  return (
    <div className="min-h-screen pb-48 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Header Section */}
      <div className="bg-surface-container-low px-8 pt-10 pb-16 rounded-b-[48px] shadow-sm mb-12 border-b border-outline-low/5 relative overflow-hidden">
        {/* Animated Background Elements */}
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-operational-cyan/5 rounded-full blur-[100px] -translate-y-1/2 translate-x-1/2" />
        
        <div className="max-w-7xl mx-auto space-y-8 relative z-10">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-10">
            <div className="space-y-3">
              <div className="flex items-center gap-5">
                <div className="p-4 bg-operational-cyan text-black rounded-[20px] shadow-xl shadow-operational-cyan/20">
                  <Building2 className="w-8 h-8" />
                </div>
                <div>
                  <h1 className="text-headline-lg font-black tracking-tight text-foreground uppercase leading-none">
                    {t('title')}
                  </h1>
                  <p className="text-body-md text-muted-foreground/60 font-medium max-w-md mt-2">
                    {t('subtitle')}
                  </p>
                </div>
              </div>
            </div>

            {/* Status Summary */}
            <div className="flex items-center gap-4">
               <div className="px-8 py-5 bg-surface-container-lowest rounded-[32px] border border-outline-low/10 shadow-sm flex items-center gap-5 ring-1 ring-black/5">
                <div className="p-3 bg-operational-cyan/10 rounded-2xl">
                  <FileText className="w-6 h-6 text-operational-cyan" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[10px] text-muted-foreground uppercase font-black tracking-widest mb-1">Status</span>
                  <div className="flex items-center gap-2">
                    <span className="text-body-md font-bold text-foreground">Verified</span>
                    <Badge className="bg-emerald-500/10 text-emerald-500 border-none text-[8px] font-black uppercase px-2 py-0">
                      Active
                    </Badge>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-8">
        <form onSubmit={handleSubmit(onSubmit)} className="grid grid-cols-1 lg:grid-cols-12 gap-8 relative z-20">

          {/* Left Column: Logo and Branding */}
          <div className="lg:col-span-4 space-y-8">
            <div className="bg-surface-container-low rounded-[40px] p-10 shadow-xl border border-outline-low/5 relative overflow-hidden group">
              <div className="absolute top-0 right-0 w-64 h-64 bg-operational-cyan/5 rounded-full -translate-y-1/2 translate-x-1/2 blur-3xl transition-transform duration-1000 group-hover:scale-150" />
              
              <div className="space-y-8 relative z-10">
                <div className="flex items-center gap-4">
                  <div className="p-2.5 bg-operational-cyan/10 rounded-xl text-operational-cyan">
                    <ImageIcon className="w-5 h-5" />
                  </div>
                  <h3 className="text-label-sm font-black uppercase tracking-widest">{t('fields.logo')}</h3>
                </div>

                <div className="relative group aspect-square rounded-[32px] border-2 border-dashed border-outline-low/20 hover:border-operational-cyan transition-all overflow-hidden flex flex-col items-center justify-center bg-surface-container-lowest shadow-inner">
                  {logoPreview ? (
                    <>
                      <Image src={logoPreview} alt={t('placeholders.logo_alt')} className="w-full h-full object-contain p-8" fill />
                      <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4 backdrop-blur-sm">
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          onClick={() => document.getElementById('logo-upload')?.click()}
                          className="w-14 h-14 bg-white/10 hover:bg-white/20 text-white rounded-2xl transition-all"
                        >
                          <Upload className="w-6 h-6" />
                        </Button>
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          onClick={removeLogo}
                          className="w-14 h-14 bg-red-500/10 hover:bg-red-500 text-white rounded-2xl transition-all"
                        >
                          <Trash2 className="w-6 h-6" />
                        </Button>
                      </div>
                    </>
                  ) : (
                    <div 
                      onClick={() => document.getElementById('logo-upload')?.click()}
                      className="flex flex-col items-center gap-4 cursor-pointer text-center p-8"
                    >
                      <div className="p-6 bg-surface-container-low rounded-3xl group-hover:bg-operational-cyan/10 transition-all group-hover:scale-110">
                        <ImageIcon className="w-10 h-10 text-muted-foreground/40" />
                      </div>
                      <span className="text-[10px] font-black text-muted-foreground/60 uppercase tracking-widest">
                        {t('upload_logo')}
                      </span>
                    </div>
                  )}
                  <input 
                    id="logo-upload"
                    type="file" 
                    accept="image/*" 
                    className="hidden" 
                    onChange={handleLogoChange}
                  />
                </div>
                
                <div className="p-6 bg-surface-container-highest/20 rounded-2xl border border-white/5">
                  <p className="text-[10px] text-muted-foreground/60 font-medium uppercase tracking-widest leading-loose">
                    {t('logo_hint')}
                  </p>
                </div>
              </div>
            </div>
          </div>

          {/* Middle and Right Columns: Form Fields */}
          <div className="lg:col-span-8 space-y-8">
            {/* Identity Section */}
            <div className="bg-surface-container-low rounded-[40px] p-10 shadow-xl border border-outline-low/5 space-y-10">
              <div className="flex items-center gap-4">
                <div className="p-2.5 bg-operational-cyan/10 rounded-xl text-operational-cyan">
                  <Building2 className="w-6 h-6" />
                </div>
                <h3 className="text-label-sm font-black uppercase tracking-widest">{t('sections.identity')}</h3>
              </div>

              <div className="grid grid-cols-1 gap-8">
                <div className="space-y-3">
                  <Label className="text-[10px] font-black uppercase text-muted-foreground/40 tracking-[0.2em] ps-1">
                    {t('fields.name')}
                  </Label>
                  <div className="relative group">
                    <Building2 className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground/20 group-focus-within:text-operational-cyan transition-colors" />
                    <Input 
                      {...register('name')}
                      placeholder={t('placeholders.name')}
                      className="h-16 pl-14 font-black bg-surface-container-lowest border border-outline-low/10 rounded-2xl focus:ring-4 focus:ring-operational-cyan/10 transition-all"
                    />
                  </div>
                  {errors.name && <p className="text-label-xs text-red-500 font-black uppercase tracking-widest ps-1">{errors.name.message}</p>}
                </div>

                <div className="space-y-3">
                  <Label className="text-[10px] font-black uppercase text-muted-foreground/40 tracking-[0.2em] ps-1">
                    {t('fields.address')}
                  </Label>
                  <div className="relative group">
                    <MapPin className="absolute left-4 top-5 w-5 h-5 text-muted-foreground/20 group-focus-within:text-operational-cyan transition-colors" />
                    <Textarea 
                      {...register('address')}
                      placeholder={t('placeholders.address')}
                      className="min-h-[120px] pl-14 pt-5 font-black bg-surface-container-lowest border border-outline-low/10 rounded-2xl focus:ring-4 focus:ring-operational-cyan/10 transition-all resize-none"
                    />
                  </div>
                  {errors.address && <p className="text-label-xs text-red-500 font-black uppercase tracking-widest ps-1">{errors.address.message}</p>}
                </div>
              </div>
            </div>

            {/* Contact & Legal Section */}
            <div className="bg-surface-container-low rounded-[40px] p-10 shadow-xl border border-outline-low/5 space-y-10">
              <div className="flex items-center gap-4">
                <div className="p-2.5 bg-operational-cyan/10 rounded-xl text-operational-cyan">
                  <Phone className="w-6 h-6" />
                </div>
                <h3 className="text-label-sm font-black uppercase tracking-widest">{t('sections.contact')} & {t('sections.legal')}</h3>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-3">
                  <Label className="text-[10px] font-black uppercase text-muted-foreground/40 tracking-[0.2em] ps-1">
                    {t('fields.phone')}
                  </Label>
                  <div className="relative group">
                    <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground/20 group-focus-within:text-operational-cyan transition-colors" />
                    <Input 
                      {...register('phone')}
                      dir="ltr"
                      placeholder={t('placeholders.phone')}
                      className="h-16 pl-14 font-black bg-surface-container-lowest border border-outline-low/10 rounded-2xl focus:ring-4 focus:ring-operational-cyan/10 transition-all"
                    />
                  </div>
                  {errors.phone && <p className="text-label-xs text-red-500 font-black uppercase tracking-widest ps-1">{errors.phone.message}</p>}
                </div>

                <div className="space-y-3">
                  <Label className="text-[10px] font-black uppercase text-muted-foreground/40 tracking-[0.2em] ps-1">
                    {t('fields.email')}
                  </Label>
                  <div className="relative group">
                    <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground/20 group-focus-within:text-operational-cyan transition-colors" />
                    <Input 
                      {...register('email')}
                      dir="ltr"
                      placeholder={t('placeholders.email')}
                      className="h-16 pl-14 font-black bg-surface-container-lowest border border-outline-low/10 rounded-2xl focus:ring-4 focus:ring-operational-cyan/10 transition-all"
                    />
                  </div>
                  {errors.email && <p className="text-label-xs text-red-500 font-black uppercase tracking-widest ps-1">{errors.email.message}</p>}
                </div>

                <div className="space-y-3">
                  <Label className="text-[10px] font-black uppercase text-muted-foreground/40 tracking-[0.2em] ps-1">
                    {t('fields.tax_number')}
                  </Label>
                  <div className="relative group">
                    <FileText className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground/20 group-focus-within:text-operational-cyan transition-colors" />
                    <Input 
                      {...register('tax_number')}
                      dir="ltr"
                      className="h-16 pl-14 font-mono font-black bg-surface-container-lowest border border-outline-low/10 rounded-2xl focus:ring-4 focus:ring-operational-cyan/10 transition-all"
                    />
                  </div>
                </div>

                <div className="space-y-3">
                  <Label className="text-[10px] font-black uppercase text-muted-foreground/40 tracking-[0.2em] ps-1">
                    {t('fields.commercial_registration')}
                  </Label>
                  <div className="relative group">
                    <FileText className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground/20 group-focus-within:text-operational-cyan transition-colors" />
                    <Input 
                      {...register('commercial_registration')}
                      dir="ltr"
                      className="h-16 pl-14 font-mono font-black bg-surface-container-lowest border border-outline-low/10 rounded-2xl focus:ring-4 focus:ring-operational-cyan/10 transition-all"
                    />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </form>

        {/* Floating Action Bar */}
        <div className={cn(
          "fixed bottom-10 left-1/2 -translate-x-1/2 z-50 w-full max-w-2xl px-4 transition-all duration-500",
          isDirty ? "translate-y-0 opacity-100" : "translate-y-20 opacity-0 pointer-events-none"
        )}>
          <div className="bg-surface-container-highest/90 backdrop-blur-2xl border border-white/10 rounded-[40px] p-4 shadow-[0_32px_64px_rgba(0,0,0,0.5)] flex items-center justify-between gap-8 ring-1 ring-white/5">
            <div className="ps-6 flex items-center gap-5">
              <div className="w-12 h-12 rounded-[18px] bg-operational-cyan flex items-center justify-center shadow-lg shadow-operational-cyan/20">
                <Save className="w-6 h-6 text-black" />
              </div>
              <div>
                <p className="text-label-xs font-black text-white uppercase tracking-[0.2em]">Unsaved Changes</p>
                <p className="text-[9px] text-white/40 uppercase font-black tracking-[0.3em]">Profile Sync Pending</p>
              </div>
            </div>
            
            <div className="flex items-center gap-3 pe-2">
              <Button 
                variant="ghost" 
                onClick={() => reset()}
                className="px-6 h-12 text-white/50 hover:text-white hover:bg-white/5 rounded-xl font-black uppercase text-[10px] tracking-widest"
              >
                {tCommon('cancel')}
              </Button>
              <Button 
                onClick={handleSubmit(onSubmit)}
                disabled={isPending}
                className="px-10 h-12 bg-operational-cyan text-black hover:bg-operational-cyan/90 rounded-xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-operational-cyan/20 flex items-center gap-3 transition-all hover:scale-105 active:scale-95"
              >
                {isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <CheckCircle2 className="w-4 h-4" />}
                {tCommon('save')}
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React from 'react';

import { PERMISSION_MATRIX, type ResourceType, type ActionType, type UserRole } from '@/types/rbac';
import { 
