                    {module.resources.map((resource) => (
                      <tr key={resource} className="group hover:bg-surface-container-high/30 transition-all duration-300 h-24">
                        <td className="sticky start-0 z-20 bg-surface-container-low group-hover:bg-surface-container-high transition-colors px-12 text-label-sm font-bold text-foreground/80">
