                            <div className="w-1.5 h-10 rounded-full bg-operational-cyan/10 group-hover:bg-operational-cyan transition-all duration-500" />
                          </div>
                        </td>
                        {ROLES.map((role) => {
                          const permissions = PERMISSION_MATRIX[role]?.[resource] ?? [];
                          const hasFull = permissions.includes('approve') || permissions.includes('edit');
                          const hasRead = permissions.includes('view') && !hasFull;
                          const hasNone = permissions.length === 0;

                          return (
                            <td key={`${role}-${resource}`} className="px-6 text-center">
                              <div className="flex items-center justify-center">
                                {hasFull && (
                                  <div className="w-12 h-12 rounded-[18px] bg-emerald-500/10 text-emerald-500 flex items-center justify-center border border-emerald-500/10 shadow-sm transition-all hover:scale-115">
                                    <Check className="w-6 h-6 stroke-[3px]" />
                                  </div>
                                )}
                                {hasRead && (
                                  <div className="w-12 h-12 rounded-[18px] bg-surface-container-high text-operational-cyan flex items-center justify-center border border-outline-low/5 shadow-sm transition-all hover:scale-115">
                                    <Eye className="w-6 h-6" />
                                  </div>
                                )}
                                {hasNone && (
                                  <div className="w-12 h-12 rounded-[18px] bg-status-error/10 text-status-error flex items-center justify-center border border-status-error/10 transition-all hover:scale-115">
                                    <div className="w-5 h-5 rounded-full border-2 border-current flex items-center justify-center">
                                        <div className="w-3 h-0.5 bg-current rotate-45" />
                                    </div>
                                  </div>
                                )}
                              </div>
                            </td>
                          );
                        })}
                      </tr>
                    ))}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Floating Action Bar */}
        <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-50 flex justify-center px-6 w-full max-w-lg">
          <div className="bg-surface-container-highest/90 backdrop-blur-3xl border border-white/10 p-3 rounded-[2.5rem] flex items-center gap-3 shadow-[0_32px_64px_-12px_rgba(0,0,0,0.6)] ring-1 ring-white/5 w-full">
            <Button 
              variant="ghost" 
              className="flex-1 rounded-[1.75rem] bg-operational-cyan hover:bg-operational-cyan/90 text-black gap-3 h-16 font-black uppercase text-[11px] tracking-[0.2em] shadow-xl shadow-operational-cyan/20 transition-all duration-500 hover:scale-[1.02] active:scale-95"
