                    <SelectTrigger className="bg-surface-container-lowest border border-outline-low/10 rounded-2xl h-14 font-black text-body-sm focus:ring-4 focus:ring-operational-cyan/10 transition-all px-6">
                      <SelectValue placeholder={t('select_language')} />
                    </SelectTrigger>
                    <SelectContent className="bg-surface-container-low border-outline-low/50 rounded-2xl shadow-2xl p-2">
                      <SelectItem value="en" className="focus:bg-operational-cyan/10 focus:text-operational-cyan rounded-xl py-3 font-black uppercase">{tCommon('locales.en')}</SelectItem>
                      <SelectItem value="ar" className="focus:bg-operational-cyan/10 focus:text-operational-cyan rounded-xl py-3 font-black uppercase">{tCommon('locales.ar')}</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
            </div>

            {/* SMTP Config */}
            <div className="bg-surface-container-low rounded-[40px] p-8 shadow-sm border border-outline-low/5 space-y-8">
              <div className="flex items-center gap-4">
                <div className="p-2.5 bg-operational-cyan/10 rounded-xl text-operational-cyan">
                  <Mail className="w-5 h-5" />
                </div>
                <h3 className="text-label-sm font-black uppercase tracking-widest">Mail Delivery</h3>
              </div>

              <div className="space-y-6">
                <div className="space-y-3">
                  <Label className="text-[10px] font-black uppercase text-muted-foreground/40 tracking-[0.2em] ps-1">
                    {t('sender_name')}
                  </Label>
                  <Input
                    {...register('sender_name')}
                    className="bg-surface-container-lowest border border-outline-low/10 rounded-2xl h-14 font-black text-body-sm px-6"
                  />
                </div>

                <div className="space-y-3">
                  <Label className="text-[10px] font-black uppercase text-muted-foreground/40 tracking-[0.2em] ps-1">
                    {t('reply_to_email')}
                  </Label>
                  <Input
                    {...register('reply_to_email')}
                    dir="ltr"
                    className="bg-surface-container-lowest border border-outline-low/10 rounded-2xl h-14 font-black text-body-sm px-6"
                  />
                </div>

                <Button variant="outline" className="w-full h-14 rounded-2xl border-dashed border-operational-cyan/20 text-operational-cyan font-black uppercase text-[10px] tracking-widest hover:bg-operational-cyan/5 transition-all">
                   Manage SMTP Vault
                </Button>
              </div>
            </div>
          </div>
        </form>
      </div>

      {/* Floating Action Bar */}
      <div className={cn(
        "fixed bottom-10 left-1/2 -translate-x-1/2 z-50 w-full max-w-2xl px-4 transition-all duration-500",
        isDirty ? "translate-y-0 opacity-100" : "translate-y-20 opacity-0 pointer-events-none"
      )}>
        <div className="bg-surface-container-highest/90 backdrop-blur-2xl border border-white/10 rounded-[40px] p-4 shadow-[0_32px_64px_rgba(0,0,0,0.5)] flex items-center justify-between gap-8 ring-1 ring-white/5">
          <div className="ps-6 flex items-center gap-5">
            <div className="w-12 h-12 rounded-[18px] bg-operational-cyan flex items-center justify-center shadow-lg shadow-operational-cyan/20">
              <Save className="w-6 h-6 text-black" />
            </div>
            <div>
              <p className="text-label-xs font-black text-white uppercase tracking-[0.2em]">Unsaved Changes</p>
              <p className="text-[9px] text-white/40 uppercase font-black tracking-[0.3em]">Sync Required</p>
            </div>
          </div>

          <div className="flex items-center gap-3 pe-2">
            <Button 
              variant="ghost" 
              onClick={() => reset()}
              className="px-6 h-12 text-white/50 hover:text-white hover:bg-white/5 rounded-xl font-black uppercase text-[10px] tracking-widest"
            >
              {t('cancel')}
            </Button>
            <Button 
              onClick={handleSubmit(onSubmit)}
              disabled={isPending}
              className="px-10 h-12 bg-operational-cyan text-black hover:bg-operational-cyan/90 rounded-xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-operational-cyan/20 flex items-center gap-3 transition-all hover:scale-105 active:scale-95"
            >
              {isPending ? <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin" /> : <CheckCircle2 className="w-4 h-4" />}
              {t('save_all')}
            </Button>
          </div>
        </div>
      </div>

      <PostConfirmDialog
        open={isConfirmOpen}
        onOpenChange={setIsConfirmOpen}
        onConfirm={handleConfirm}
        title={t('confirm_base_currency_title')}
        description={t('confirm_base_currency_warning')}
        confirmText={tCommon('save')}
        variant="destructive"
      />
    </div>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { ShieldCheck, Search, Shield, Users, Edit, Eye } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { useAdminUsers, type AdminUserRow } from '@/features/admin/hooks/useAdminUsers';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { MetricCard } from '@/components/ui/metric-card';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { ClientOnlyTime } from '@/components/shared/ClientOnlyTime';

const roleVariants: Record<string, string> = {
  ADMIN: 'bg-rose-500/10 text-rose-400 border-rose-500/20',
  INV_MGR: 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20',
  APPROVER: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
  WH_KEEPER: 'bg-amber-500/10 text-amber-400 border-amber-500/20',
  PROC_OFFICER: 'bg-blue-500/10 text-blue-400 border-blue-500/20',
  AUDITOR: 'bg-surface-container text-muted-foreground border-border-surface',
  VIEWER: 'bg-slate-500/10 text-slate-400 border-slate-500/20',
};

export function UserListClient({ locale: _locale }: { locale: string }) {
  const t = useTranslations('admin.users');
  const tCommon = useTranslations('common');
  const router = useRouter();
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');

  const { data, isLoading } = useAdminUsers({ page });

  const stats = useMemo(() => {
    const users = data?.data || [];
    return {
      total: data?.meta?.total || 0,
      admins: users.filter(u => u.role === 'ADMIN').length,
      ops: users.filter(u => u.role !== 'ADMIN').length,
    };
  }, [data]);

  const columns = useMemo<ColumnDef<AdminUserRow, unknown>[]>(() => [
    {
      accessorKey: 'name',
      header: t('name'),
      cell: ({ row }) => (
        <div className="flex flex-col gap-0.5">
          <span className="font-bold text-label-sm">{row.original.name}</span>
          <span className="text-label-xs opacity-40 font-mono" dir="ltr">{row.original.email}</span>
        </div>
      ),
    },
    {
      accessorKey: 'role',
      header: t('role'),
      cell: ({ row }) => (
        <Badge variant="outline" className={`text-[10px] font-black tracking-widest uppercase rounded-xl px-3 py-1 border-none ${roleVariants[row.original.role] ?? 'bg-surface-container text-muted-foreground'}`}>
          {row.original.role}
        </Badge>
      ),
    },
    {
      accessorKey: 'status',
      header: t('status'),
      cell: ({ row }) => (
        <StatusBadge status={row.original.status || 'ACTIVE'} className="rounded-full px-3 h-6 text-[10px] font-black tracking-wider" />
      ),
    },
    {
      accessorKey: 'language',
      header: t('language'),
      cell: ({ row }) => (
        <span className="text-[10px] font-black tracking-widest uppercase opacity-60 px-3 py-1 bg-surface-container-high/50 rounded-xl">
          {row.original.language || 'en'}
        </span>
      ),
    },
    {
      accessorKey: 'scopes',
      header: t('scopes'),
      cell: ({ row }) => {
        const scopeLabels: string[] = [];
        row.original.scopes.forEach((s) => {
          const parts: string[] = [];
          if (s.branch_id) parts.push(`B:${s.branch_id}`);
          if (s.warehouse_id) parts.push(`W:${s.warehouse_id}`);
          if (s.department_id) parts.push(`D:${s.department_id}`);
          if (parts.length) scopeLabels.push(parts.join(', '));
        });
        return (
          <div className="flex flex-wrap gap-2">
            {scopeLabels.length > 0 ? scopeLabels.map((sl, idx) => (
              <span key={idx} dir="ltr" className="text-[10px] font-mono font-bold opacity-60 bg-surface-container-high/50 px-2 py-1 rounded-lg">
                {sl}
              </span>
            )) : <span className="opacity-20 text-label-xs italic">— {t('no_scope')} —</span>}
          </div>
        );
      },
    },
    {
      accessorKey: 'created_at',
      header: tCommon('created_at'),
      cell: ({ row }) => (
        <span className="text-label-xs font-mono opacity-40" dir="ltr">
          {row.original.created_at ? <ClientOnlyTime date={row.original.created_at} mode="datetime" /> : '—'}
        </span>
      ),
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end gap-3">
          <PermissionGate action="edit" resource="admin">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-bold uppercase text-operational-cyan hover:bg-operational-cyan/10 h-9 px-4 rounded-xl transition-all"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/admin/users/${row.original.id}/edit`);
              }}
            >
              <Edit className="w-3.5 h-3.5 me-2" />
              {tCommon('edit')}
            </Button>
          </PermissionGate>
          <Button 
            variant="ghost" 
            size="sm" 
            className="text-label-xs font-bold uppercase text-muted-foreground hover:text-foreground hover:bg-surface-container-highest/40 h-9 px-4 rounded-xl transition-all"
            onClick={(e) => {
              e.stopPropagation();
              router.push(`/admin/users/${row.original.id}`);
            }}
          >
            <Eye className="w-3.5 h-3.5 me-2" />
            {tCommon('view')}
          </Button>
        </div>
      ),
    },
  ], [t, tCommon, router]);

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-1000 space-y-12">
      {/* Metrics Header */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <MetricCard
          label={tCommon('total_users') || t('total_identities')}
          value={stats.total}
          icon={Users}
          color="cyan"
        />
        <MetricCard
          label={tCommon('admins') || t('elevated_access')}
          value={stats.admins}
          icon={ShieldCheck}
          color="rose"
        />
        <MetricCard
          label={tCommon('operators') || t('standard_ops')}
          value={stats.ops}
          icon={Shield}
          color="cyan"
        />
      </div>

      <div className="bg-surface-container-low/30 rounded-[32px] p-8">
        <DataTable
          columns={columns}
          data={data?.data ?? []}
          isLoading={isLoading}
          collectionName="admin_users"
          onRowClick={(row: AdminUserRow) => router.push(`/admin/users/${row.id}`)}
          pagination={data?.meta ? {
            page: page,
            pageSize: 10,
            total: data.meta.total,
            totalPages: data.meta.total_pages,
            onPageChange: setPage
          } : undefined}
          filters={
            <div className="flex flex-wrap items-end gap-8 w-full py-6 px-10 bg-surface-container-high/40 rounded-3xl mb-8">
              <div className="flex flex-col gap-3 min-w-[320px] flex-1">
                <label className="text-label-xs font-black uppercase text-muted-foreground/30 tracking-widest">{tCommon('search')}</label>
                <div className="relative group">
                  <Input
                    placeholder={t('search_placeholder')}
                    value={search}
                    onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                    className="w-full bg-surface-container-highest/50 border-none h-14 px-12 text-label-sm font-bold rounded-2xl transition-all group-hover:bg-surface-container-highest/80 focus:ring-2 focus:ring-operational-cyan/20"
                  />
                  <Search className="absolute start-4 top-1/2 -translate-y-1/2 w-4.5 h-4.5 text-muted-foreground/30 group-focus-within:text-operational-cyan transition-colors" />
                </div>
              </div>
            </div>
          }
        />
      </div>
    </div>
  );
}

'use client';

import { useEffect, useMemo } from 'react';
import { useRouter } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { useForm, useWatch } from 'react-hook-form';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { zodResolver } from '@hookform/resolvers/zod';
import { useAdminUser, useAdminUserMutations, UserFormSchema, type UserFormValues } from '@/features/admin/hooks/useAdminUsers';
import { useAuth } from '@/providers/AuthProvider';
import { type UserRole } from '@/types/rbac';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { MasterDataFormLayout } from '@/features/master-data/components/MasterDataFormLayout';
import { User, Mail, Shield, MapPin, Warehouse, Building2, CheckCircle2, Globe, Power, AlertTriangle } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';

const ALL_ROLES: UserRole[] = ['ADMIN', 'INV_MGR', 'APPROVER', 'WH_KEEPER', 'PROC_OFFICER', 'AUDITOR', 'VIEWER'];

const MOCK_BRANCHES = [
  { id: 'br-1', name_ar: 'الفرع الرئيسي', name_en: 'Main Branch' },
  { id: 'br-2', name_ar: 'فرع الشمال', name_en: 'North Branch' },
];

const MOCK_WAREHOUSES = [
  { id: 'wh-1', branch_id: 'br-1', name_ar: 'المستودع الرئيسي', name_en: 'Main Warehouse' },
  { id: 'wh-2', branch_id: 'br-1', name_ar: 'المستودع الثانوي', name_en: 'Secondary Warehouse' },
  { id: 'wh-3', branch_id: 'br-2', name_ar: 'لوجستيات الشمال', name_en: 'North Logistics' },
];

const MOCK_DEPARTMENTS = [
  { id: 'dep-1', warehouse_id: 'wh-1', name_ar: 'المطبخ', name_en: 'Kitchen' },
  { id: 'dep-2', warehouse_id: 'wh-1', name_ar: 'المخزن', name_en: 'Store' },
  { id: 'dep-3', warehouse_id: 'wh-3', name_ar: 'التوزيع', name_en: 'Distribution' },
];

interface Props {
  id: string | null;
  createTitle: string;
  editTitle: string;
  locale: string;
  isReadOnly?: boolean;
}

export function UserFormClient({ id, createTitle, editTitle, locale, isReadOnly = false }: Props) {
  const t = useTranslations('admin.users');
  const _router = useRouter();
  const { data, isLoading } = useAdminUser(id);
  const { user: currentUser } = useAuth();
  const { createUser, updateUser, isLastActiveAdmin } = useAdminUserMutations();

  const isSelf = currentUser?.id === id;
  const isAuditor = currentUser?.role === 'AUDITOR' || isReadOnly;

  const { register, handleSubmit, reset, setValue, control, formState: { isSubmitting, isDirty, errors } } = useForm<UserFormValues>({
    resolver: zodResolver(UserFormSchema),
    defaultValues: {
      name: '',
      email: '',
      role: 'WH_KEEPER',
      status: 'ACTIVE',
      language: 'en',
      branch_ids: [],
      warehouse_ids: [],
      department_ids: [],
    },
  });

  const { router: guardedRouter } = useUnsavedChangesGuard(isDirty);

  const selectedBranches = useWatch({ control, name: 'branch_ids' });
  const selectedWarehouses = useWatch({ control, name: 'warehouse_ids' });
  const selectedRole = useWatch({ control, name: 'role' });
  const selectedStatus = useWatch({ control, name: 'status' });
  const selectedDepartments = useWatch({ control, name: 'department_ids' });

  // Security Check: Is this the last admin?
  const isLastAdmin = useMemo(() => {
    if (!id) return false;
    return isLastActiveAdmin(id);
  }, [id, isLastActiveAdmin]);

  // Cascading Logic: Warehouses depend on Branches
  const filteredWarehouses = useMemo(() => {
    if (!selectedBranches?.length) return [];
    return MOCK_WAREHOUSES.filter(wh => selectedBranches.includes(wh.branch_id));
  }, [selectedBranches]);

  // Cascading Logic: Departments depend on Warehouses
  const filteredDepartments = useMemo(() => {
    if (!selectedWarehouses?.length) return [];
    return MOCK_DEPARTMENTS.filter(dep => selectedWarehouses.includes(dep.warehouse_id));
  }, [selectedWarehouses]);

  // Auto-reset dependent selections when parent changes
  useEffect(() => {
    const currentWhs = selectedWarehouses || [];
    const validWhs = currentWhs.filter(whId => filteredWarehouses.some(f => f.id === whId));
    if (validWhs.length !== currentWhs.length) {
      setValue('warehouse_ids', validWhs);
    }
  }, [filteredWarehouses, setValue, selectedWarehouses]);

  useEffect(() => {
    const currentDeps = selectedDepartments || [];
    const validDeps = currentDeps.filter(depId => filteredDepartments.some(f => f.id === depId));
    if (validDeps.length !== currentDeps.length) {
      setValue('department_ids', validDeps);
    }
  }, [filteredDepartments, setValue, selectedDepartments]);

  useEffect(() => {
    if (data) {
      reset({
        name: data.name,
        email: data.email,
        role: data.role as UserRole,
        status: data.status as 'ACTIVE' | 'INACTIVE' || 'ACTIVE',
        language: (data.language as 'en' | 'ar') || 'en',
        branch_ids: data.scopes.filter(s => s.branch_id).map(s => s.branch_id!),
        warehouse_ids: data.scopes.filter(s => s.warehouse_id).map(s => s.warehouse_id!),
        department_ids: data.scopes.filter(s => s.department_id).map(s => s.department_id!),
      });
    }
  }, [data, reset]);

  const onSubmit = handleSubmit(async (values) => {
    if (id) {
      await updateUser.mutateAsync({ ...values, id });
    } else {
      await createUser.mutateAsync(values);
    }
    guardedRouter.push('/admin/users');
  });


  if (isLoading && id) {
    return (
      <div className="flex flex-col items-center justify-center h-64 gap-4">
        <div className="w-10 h-10 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin" />
        <span className="text-label-xs font-semibold uppercase text-muted-foreground animate-pulse">{t('syncing_identity')}</span>
      </div>
    );
  }

  return (
    <MasterDataFormLayout
      title={id ? editTitle : createTitle}
      backHref="/admin/users"
      isSaving={isSubmitting}
      onSubmit={onSubmit}
      onCancel={() => guardedRouter.push('/admin/users', { skipGuard: true })}
      resource="admin"
      saveAction={id ? 'edit' : 'create'}
      hideSave={isReadOnly}
    >
      <div className="grid grid-cols-1 md:grid-cols-12 gap-10">
        {/* Main Identity & Access */}
        <div className="md:col-span-8 space-y-10">
          {/* Identity Section */}
          <section className="space-y-6">
            <div className="flex items-center gap-3 mb-2">
              <div className="w-10 h-10 rounded-sm bg-cyan-500/10 border border-cyan-500/20 flex items-center justify-center">
                <User className="w-5 h-5 text-cyan-500" />
              </div>
              <div>
                <h2 className="text-title-sm font-semibold uppercase">{t('user_identity')}</h2>
                <p className="text-label-xs text-muted-foreground/60 uppercase font-bold">{t('profile_metadata')}</p>
              </div>
            </div>

            <Card className="bg-surface-container-low border-outline-low rounded-sm shadow-none">
              <CardContent className="p-8 grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <Label className="text-label-xs font-semibold uppercase text-text-muted flex items-center gap-2">
                    <User className="w-3 h-3" /> {t('name')}
                  </Label>
                  <Input 
                    {...register('name')} 
                    disabled={isAuditor} 
                    dir="auto"
                    className={`h-11 bg-surface-container-highest/30 border-outline-low rounded-sm focus:ring-cyan-500/50 font-bold ${errors.name ? 'border-rose-500' : ''}`}
                  />
                  {errors.name?.message && (
                    <p className="text-label-xxs text-rose-500 font-bold uppercase">
                      {t(errors.name.message as Parameters<typeof t>[0])}
                    </p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label className="text-label-xs font-semibold uppercase text-text-muted flex items-center gap-2">
                    <Mail className="w-3 h-3" /> {t('email')}
                  </Label>
                  <Input 
                    dir="ltr" 
                    {...register('email')} 
                    disabled={isAuditor}
                    className={`h-11 bg-surface-container-highest/30 border-outline-low rounded-sm focus:ring-cyan-500/50 font-mono font-bold ${errors.email ? 'border-rose-500' : ''}`}
                  />
                  {errors.email?.message && (
                    <p className="text-label-xxs text-rose-500 font-bold uppercase">
                      {t(errors.email.message as Parameters<typeof t>[0])}
                    </p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label className="text-label-xs font-semibold uppercase text-text-muted flex items-center gap-2">
                    <Globe className="w-3 h-3" /> {t('language')}
                  </Label>
                  <select
                    {...register('language')}
                    disabled={isAuditor}
                    className="h-11 px-4 bg-surface-container-highest/30 border border-outline-low rounded-sm w-full text-label-sm font-bold focus:outline-none focus:ring-1 focus:ring-cyan-500/50 disabled:opacity-50"
                  >
                    <option value="en">{t('lang_en')}</option>
                    <option value="ar">{t('lang_ar')}</option>
                  </select>
                </div>
              </CardContent>
            </Card>
          </section>

          {/* Scopes Section */}
          <section className="space-y-6">
            <div className="flex items-center gap-3 mb-2">
              <div className="w-10 h-10 rounded-sm bg-cyan-500/10 border border-cyan-500/20 flex items-center justify-center">
                <MapPin className="w-5 h-5 text-cyan-500" />
              </div>
              <div>
                <h2 className="text-title-sm font-semibold uppercase">{t('access_scopes')}</h2>
                <p className="text-label-xs text-muted-foreground/60 uppercase font-bold">{t('organizational_units')}</p>
              </div>
            </div>

            <Card className="bg-surface-container-low border-outline-low rounded-sm shadow-none">
              <CardContent className="p-8 space-y-10">
                <MultiSelect
                  label={t('branch_scope')}
                  icon={<Building2 className="w-3 h-3" />}
                  options={MOCK_BRANCHES.map(b => ({ id: b.id, label: locale === 'ar' ? b.name_ar : b.name_en }))}
                  selected={selectedBranches}
                  onChange={(v) => setValue('branch_ids', v)}
                  disabled={isAuditor || isSelf}
                  t={t}
                />

                <MultiSelect
                  label={t('warehouse_scope')}
                  icon={<Warehouse className="w-3 h-3" />}
                  options={filteredWarehouses.map(w => ({ id: w.id, label: locale === 'ar' ? w.name_ar : w.name_en }))}
                  selected={selectedWarehouses}
                  onChange={(v) => setValue('warehouse_ids', v)}
                  disabled={isAuditor || isSelf || !selectedBranches.length}
                  t={t}
                />

                <MultiSelect
                  label={t('department_scope')}
                  icon={<Building2 className="w-3 h-3" />}
