'use client';

import { useEffect } from 'react';

import { useTranslations } from 'next-intl';
import { useUnsavedChangesGuard } from '@/lib/unsaved-changes/useUnsavedChangesGuard';
import { useForm, useWatch } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Building2, ShieldCheck, Trash2 } from 'lucide-react';

import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { useState } from 'react';
import { PostConfirmDialog } from '@/components/shared/PostConfirmDialog';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { MasterDataFormLayout } from '@/features/master-data/components/MasterDataFormLayout';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import {
 useBranch,
 useCreateBranch,
 useUpdateBranch,
 useDeleteBranch,
} from '@/features/branches/hooks/useBranches';
import { BranchFormSchema, type BranchFormValues } from '@/types/master-data';
import { useConflictHandler } from '@/core/concurrency/useConflictHandler';
import { ConflictDialog } from '@/core/concurrency/ConflictDialog';

import { useAbortController } from '@/hooks/useAbortController';

interface Props {
  id: string | null;
  createTitle: string;
  editTitle: string;
  viewTitle?: string;
  locale: string;
  isReadOnly?: boolean;
}

export function BranchFormClient({ id, createTitle, editTitle, viewTitle, locale: _locale, isReadOnly = false }: Props) {
  const t = useTranslations('common');
  const tb = useTranslations('master_data.branches');
  const abortController = useAbortController();
  
  const { 
    register, 
    handleSubmit, 
    reset, 
    setValue, 
    control, 
    formState: { errors, isDirty, isValid } 
  } = useForm<BranchFormValues>({
    resolver: zodResolver(BranchFormSchema),
    disabled: isReadOnly,
    defaultValues: { code: '', name_ar: '', name_en: '', is_active: true, version: undefined },
  });

  const { 
    data, 
    isLoading, 
    isError, 
    refetch,
    fetchStatus 
  } = useBranch(id);
  const create = useCreateBranch();
  const conflict = useConflictHandler('branch', id ?? '');
  const update = useUpdateBranch({ onConflict: conflict.triggerConflict });
  const deleteBranch = useDeleteBranch();

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  const { router: guardedRouter } = useUnsavedChangesGuard(isDirty);

  const isActive = useWatch({ control, name: 'is_active' });

  useEffect(() => {
    if (data) {
      reset({ code: data.code, name_ar: data.name_ar, name_en: data.name_en, is_active: data.is_active, version: data.version });
    }
  }, [data, reset]);

  const onSubmit = handleSubmit(async (values) => {
    if (isReadOnly) return;
    
    try {
      if (id) {
        await update.mutateAsync({ id, values, signal: abortController.signal });
      } else {
        await create.mutateAsync({ ...values, signal: abortController.signal });
      }
      reset(values);
      guardedRouter.push('/master-data/branches', { skipGuard: true });
    } catch {
      // Error handled by mutation hooks or conflict handler
    }
  });

  const handleDelete = async () => {
    if (!id) return;
    try {
      await deleteBranch.mutateAsync({ id, signal: abortController.signal });
      guardedRouter.push('/master-data/branches', { skipGuard: true });
    } catch {
      setShowDeleteConfirm(false);
    }
  };

  // Standardized Loading State
  if (id && (isLoading || (fetchStatus === 'fetching' && !data))) {
    return <PageSkeleton variant="detail" />;
  }

  // Standardized Error State (Server Error)
  if (id && isError) {
    return (
      <MasterDataFormLayout 
        title={editTitle} 
        backHref="/master-data/branches"
        onCancel={() => guardedRouter.push('/master-data/branches')}
      >
        <div className="h-[400px] flex items-center justify-center">
          <ErrorState 
            type="server_error"
            onRetry={() => refetch()}
          />
        </div>
      </MasterDataFormLayout>
    );
  }

  // Standardized Not Found State
  if (id && !data && !isLoading) {
    return (
      <MasterDataFormLayout 
        title={editTitle} 
        backHref="/master-data/branches"
        onCancel={() => guardedRouter.push('/master-data/branches')}
      >
        <div className="h-[400px] flex items-center justify-center">
          <ErrorState 
            type="not_found"
            title={tb('errors.not_found_title')}
            description={tb('errors.not_found_description')}
          />
        </div>
      </MasterDataFormLayout>
    );
  }

  const isSaving = create.isPending || update.isPending || deleteBranch.isPending;

  // Determine the display title
  const displayTitle = id 
    ? (isReadOnly ? (viewTitle || tb('view_title')) : editTitle)
    : createTitle;

  return (
    <>
    <MasterDataFormLayout
      title={displayTitle}
      backHref='/master-data/branches'
      isSaving={isSaving} saveDisabled={conflict.saveDisabled}
      onSubmit={onSubmit}
      onCancel={() => guardedRouter.push('/master-data/branches')}
      hideSave={isReadOnly}
      isDirty={isDirty}
      isValid={isValid}
      headerActions={
        id && !isReadOnly && (
          <PermissionGate action="delete" resource="master_data_branches">
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="text-status-error hover:text-status-error hover:bg-status-error/10 rounded-full w-10 h-10 transition-all duration-200"
              onClick={() => setShowDeleteConfirm(true)}
              disabled={isSaving}
            >
              <Trash2 className="w-5 h-5" />
            </Button>
          </PermissionGate>
        )
      }
    >
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Content */}
        <div className="lg:col-span-2 space-y-8">
          <Card className="bg-surface-container-low border-none overflow-hidden">
            <CardContent className="p-8 space-y-8">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                  <Building2 className="w-5 h-5 text-tertiary" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{tb('details_title') || t('details')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{tb('details_description') || t('details_desc')}</p>
                </div>
              </div>

              {/* Code */}
              <div className="space-y-2 max-w-sm">
                <Label htmlFor="branch-code" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{t('code')}</Label>
                <Input 
                  id="branch-code" 
                  dir="ltr" 
                  {...register('code')} 
                  disabled={isReadOnly}
                  className="font-mono font-semibold uppercase text-status-active" 
                  placeholder={tb('placeholders.code')} 
                />
                {errors.code && <p className="text-label-xs font-semibold text-status-error uppercase">{t(errors.code.message as string)}</p>}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Name EN */}
                <div className="space-y-2">
                  <Label htmlFor="branch-name-en" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{t('name_en')}</Label>
                  <Input 
                    id="branch-name-en" 
                    dir="ltr" 
                    {...register('name_en')} 
                    disabled={isReadOnly}
                    className="font-semibold" 
                    placeholder={tb('placeholders.name_en')} 
                  />
                  {errors.name_en && <p className="text-label-xs font-semibold text-status-error uppercase">{t(errors.name_en.message as string)}</p>}
                </div>

                {/* Name AR */}
                <div className="space-y-2">
                  <Label htmlFor="branch-name-ar" className="text-label-xs font-semibold uppercase text-muted-foreground/70">{t('name_ar')}</Label>
                  <Input 
                    id="branch-name-ar" 
                    dir="rtl" 
                    {...register('name_ar')} 
                    disabled={isReadOnly}
                    className="font-semibold text-end" 
                    placeholder={tb('placeholders.name_ar')} 
                  />
                  {errors.name_ar && <p className="text-label-xs font-semibold text-status-error uppercase">{t(errors.name_ar.message as string)}</p>}
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Sidebar */}
        <div className="space-y-8">
          <Card className="bg-surface-container-low border-none overflow-hidden">
            <CardContent className="p-8 space-y-6">
              <div className="flex items-center gap-3 pb-4 border-b border-surface-variant/10">
                <div className="w-10 h-10 rounded-md bg-tertiary-container/10 flex items-center justify-center">
                  <ShieldCheck className="w-5 h-5 text-tertiary" />
                </div>
                <div>
                  <h3 className="text-body-md font-semibold text-foreground uppercase">{t('status_label')}</h3>
                  <p className="text-label-xs font-semibold text-muted-foreground/60 uppercase mt-0.5">{t('operational_status')}</p>
                </div>
              </div>

              <div className="flex items-center justify-between p-4 bg-surface-container-highest/20 rounded-md border border-surface-variant/10 group transition-all hover:bg-surface-container-highest/30">
                <div className="space-y-1">
                  <Label htmlFor="branch-is-active" className="text-label-xs font-semibold uppercase cursor-pointer text-muted-foreground/60">{t('is_active')}</Label>
                  <p className={`text-label-sm font-semibold uppercase ${isActive ? 'text-status-active' : 'text-status-error'}`}>{isActive ? t('statuses.active') : t('statuses.inactive')}</p>
                </div>
                <Switch
                  id="branch-is-active"
                  checked={isActive}
                  onCheckedChange={(v) => setValue('is_active', v)}
                  disabled={isReadOnly}
                  className="data-[state=checked]:bg-status-active"
                />
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </MasterDataFormLayout>
      <ConflictDialog open={conflict.open} onReload={conflict.handleReload} onClose={conflict.handleClose} />

      <PostConfirmDialog
        open={showDeleteConfirm}
        onOpenChange={setShowDeleteConfirm}
        onConfirm={handleDelete}
        title={tb('delete_confirm_title')}
        description={tb('delete_confirm_desc')}
        isLoading={deleteBranch.isPending}
        variant="destructive"
      />
    </>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { Link, useRouter } from '@/i18n/navigation';
import { Plus, Building2, CheckCircle2, Search, Shield } from 'lucide-react';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { useBranches } from '@/features/branches/hooks/useBranches';
import { type Branch } from '@/types/master-data';
import { ColumnDef } from '@tanstack/react-table';
import { ClientOnlyTime } from '@/components/shared/ClientOnlyTime';
import { PageHeader } from '@/components/shared/PageHeader';
import { Input } from '@/components/ui/input';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { MetricCard } from '@/components/ui/metric-card';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import { EmptyState } from '@/components/shared/EmptyState';

export function BranchListClient({ locale }: { locale: string }) {
 const t = useTranslations('master_data.branches');
 const tc = useTranslations('common');
 const router = useRouter();
 const [, setPage] = useState(1);
 const [search, setSearch] = useState('');

  const { data, isLoading, isError, refetch } = useBranches({ search });

 const stats = useMemo(() => {
 const branches = data?.data || [];
 return {
 total: data?.meta?.total || 0,
 active: branches.filter(b => b.is_active).length,
 };
 }, [data]);

  const columns = useMemo<ColumnDef<Branch, unknown>[]>(() => [
    {
      accessorKey: 'code',
      header: t('fields.code'),
      cell: ({ row }) => (
        <span dir="ltr" className="font-mono text-label-xs font-semibold text-cyan-500 uppercase px-2 py-0.5 bg-cyan-500/5 rounded-sm whitespace-nowrap inline-block min-w-max">
          {row.original.code}
        </span>
      ),
    },
    {
      accessorKey: 'name',
      header: tc('name'),
      cell: ({ row }) => (
        <div className="flex flex-col gap-0.5">
          <span className="font-bold text-label-sm">{row.original.name_en}</span>
          <span className="text-label-xs text-muted-foreground/60" dir="rtl">{row.original.name_ar}</span>
        </div>
      ),
    },
    {
      accessorKey: 'is_active',
      header: t('fields.is_active'),
      cell: ({ row }) => (
        <StatusBadge 
          status={row.original.is_active ? 'ACTIVE' : 'INACTIVE'} className="rounded-sm h-5"
        />
      ),
    },
    {
      accessorKey: 'created_at',
      header: tc('created_at'),
      cell: ({ row }) => (
        <ClientOnlyTime 
          date={row.original.created_at} 
          mode="date" 
          className="text-label-xs text-muted-foreground/60 font-medium" 
        />
      ),
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end gap-2">
          <PermissionGate action="view" resource="master_data">
            <Button
              variant="ghost"
              size="sm"
              className="text-label-xs font-semibold uppercase text-cyan-500 hover:text-cyan-400 hover:bg-cyan-500/10 h-7"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/branches/${row.original.id}`);
              }}
            >
              {tc('view')}
            </Button>
          </PermissionGate>
          
          <PermissionGate action="edit" resource="master_data">
            <Button
              variant="ghost"
              size="sm"
              className="text-label-xs font-semibold uppercase text-emerald-500 hover:text-emerald-400 hover:bg-emerald-500/10 h-7"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/branches/${row.original.id}/edit`);
              }}
            >
              {t('edit')}
            </Button>
          </PermissionGate>
        </div>
      ),
    },
  ], [tc, t, router]);

  if (isLoading && !data) return <PageSkeleton variant="list" />;
  if (isError) return <ErrorState error={500} onRetry={() => refetch()} />;

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="space-y-4">
        <Breadcrumb items={[
          { label: tc('home'), href: `/dashboard` },
          { label: tc('master_data'), href: `/master-data` },
          { label: t('title') }
        ]} />
        <PageHeader
          title={t('title')}
          description={t('description')}
          actions={
            <PermissionGate action="create" resource="master_data">
              <Link href={`/master-data/branches/new`}>
                <Button className="h-11 px-8 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                  <Plus className="w-3.5 h-3.5 me-2" />
                  {tc('create')}
                </Button>
              </Link>
            </PermissionGate>
          }
        />
      </div>

 {/* KPI Section */}
 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
 <MetricCard
 label={tc('total_locations')}
 value={stats.total}
 icon={Building2}
 color="cyan"
 dir="ltr"
 />

 <MetricCard
 label={tc('statuses.active')}
 value={stats.active}
 icon={CheckCircle2}
 color="emerald"
 dir="ltr"
 />

 <MetricCard
 label={t('description')}
 value="100%"
 icon={Shield}
 color="indigo"
 dir="ltr"
 />
 </div>

      <DataTable
        columns={columns}
        data={data?.data ?? []}
        isLoading={isLoading}
        collectionName="master_data_branches"
        onRowClick={(r: Branch) => router.push(`/master-data/branches/${r.id}`)}
        emptyState={
          <EmptyState 
            variant="minimal"
            title={tc('no_data')}
          />
        }
        pagination={data?.meta ? {
          page: data.meta.page,
          pageSize: data.meta.page_size,
          total: data.meta.total,
          totalPages: data.meta.total_pages,
          onPageChange: setPage
        } : undefined}
        filters={
          <div className="flex flex-wrap items-end gap-6 w-full py-6 px-8 bg-surface-container-medium/30 rounded-sm">
            <div className="flex flex-col gap-2 min-w-[300px] flex-1">
              <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ps-1">{tc('search')}</label>
              <div className="relative">
                <Input
                  placeholder={tc('search')}
                  value={search}
                  onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                  className="w-full bg-surface-container-highest/30 border-none h-12 px-12 text-label-sm font-bold rounded-sm shadow-inner shadow-black/20"
                />
                <Search className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40" />
              </div>
            </div>
          </div>
        }
      />
    </div>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { Link, useRouter } from '@/i18n/navigation';
import { Plus, CheckCircle2, Search, Coins, Landmark, ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { useCurrencies } from '@/features/currencies/hooks/useCurrencies';
import { type Currency } from '@/types/master-data';
import { PageHeader } from '@/components/shared/PageHeader';
import { Input } from '@/components/ui/input';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { MetricCard } from '@/components/ui/metric-card';
import { Badge } from '@/components/ui/badge';
import { EmptyState } from '@/components/shared/EmptyState';
import { ErrorState } from '@/components/shared/ErrorState';

export function CurrencyListClient({ locale }: { locale: string }) {
 const tc = useTranslations('common');
 const t = useTranslations('master_data.currencies');
 const router = useRouter();
 const [search, setSearch] = useState('');

 const { data: currencies = [], isLoading, isError, refetch } = useCurrencies();

 const filteredCurrencies = useMemo(() => {
 if (!search) return currencies;
 const s = search.toLowerCase();
 return currencies.filter((c: Currency) => 
 c.code.toLowerCase().includes(s) || 
 c.name_en.toLowerCase().includes(s) || 
 c.name_ar.includes(s)
 );
 }, [currencies, search]);

 const stats = useMemo(() => {
 const base = currencies.find((c: Currency) => c.is_base_currency);
 return {
 total: currencies.length,
 active: currencies.filter((c: Currency) => c.is_active).length,
 baseCurrency: base ? (locale === 'ar' ? base.name_ar : base.name_en) : '---'
 };
 }, [currencies, locale]);

 const columns = useMemo<ColumnDef<Currency, unknown>[]>(() => [
 { 
 accessorKey: 'code', 
