'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { EmptyState } from '@/components/shared/EmptyState';
import { PageSkeleton } from '@/components/shared/PageSkeleton';
import { ErrorState } from '@/components/shared/ErrorState';
import { Plus, Briefcase, Search, Layers, ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { useDepartments } from '@/features/departments/hooks/useDepartments';
import { type Department } from '@/types/master-data';
import { MetricCard } from '@/components/ui/metric-card';
import { ColumnDef } from '@tanstack/react-table';
import { PageHeader } from '@/components/shared/PageHeader';
import { Input } from '@/components/ui/input';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { StatusBadge } from '@/components/shared/StatusBadge';

export function DepartmentListClient({ locale }: { locale: string }) {
  const tc = useTranslations('common');
  const t = useTranslations('master_data.departments');
  const router = useRouter();
  const [_page, setPage] = useState(1);
  const [search, setSearch] = useState('');

  const { data: queryData, isLoading, isError, refetch } = useDepartments({ search });
  const departments = queryData?.data || [];

  const stats = useMemo(() => {
    return {
      total: departments.length,
      active: departments.filter(d => d.is_active).length,
    };
  }, [departments]);

  const columns = useMemo<ColumnDef<Department, unknown>[]>(() => [
    {
      accessorKey: 'code',
      header: t('fields.code'),
      cell: ({ row }) => (
        <span dir="ltr" className="font-mono text-label-xs font-semibold text-cyan-500 uppercase px-2 py-0.5 bg-cyan-500/5 rounded-sm whitespace-nowrap inline-block min-w-max">
          {row.original.code}
        </span>
      ),
    },
    {
      accessorKey: 'name',
      header: tc('name'),
      cell: ({ row }) => (
        <div className="flex flex-col gap-0.5">
          <span className="font-bold text-label-sm">{row.original.name_en}</span>
          <span className="text-label-xs text-muted-foreground/60" dir="rtl">{row.original.name_ar}</span>
        </div>
      ),
    },
    {
      accessorKey: 'is_active',
      header: t('fields.is_active'),
      cell: ({ row }) => (
        <StatusBadge 
          status={row.original.is_active ? 'ACTIVE' : 'INACTIVE'} className="rounded-sm h-5"
        />
      ),
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end gap-2">
          <PermissionGate action="view" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-semibold uppercase text-cyan-500 hover:text-cyan-400 hover:bg-cyan-500/10 h-7"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/departments/${row.original.id}`);
              }}
            >
              {tc('view')}
            </Button>
          </PermissionGate>
          <PermissionGate action="edit" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-semibold uppercase text-amber-500 hover:text-amber-400 hover:bg-amber-500/10 h-7"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/departments/${row.original.id}/edit`);
              }}
            >
              {tc('edit')}
            </Button>
          </PermissionGate>
        </div>
      ),
    },
  ], [tc, t, locale, router]);

  if (isLoading && !queryData) return <PageSkeleton variant="list" />;
  if (isError) return <ErrorState error={500} onRetry={() => refetch()} />;

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="space-y-4">
        <Breadcrumb items={[
          { label: tc('home'), href: `/dashboard` },
          { label: tc('master_data'), href: `/master-data` },
          { label: t('title') }
        ]} />
        <PageHeader 
          title={t('title')} 
          description={t('description')}
          actions={
            <PermissionGate action="create" resource="master_data">
              <Link href={`/master-data/departments/new`}>
                <Button className="h-11 px-8 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                  <Plus className="w-3.5 h-3.5 me-2" />
                  {tc('create')}
                </Button>
              </Link>
            </PermissionGate>
          }
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={tc('total_locations')}
          value={stats.total}
          icon={Briefcase}
          color="cyan"
          dir="ltr"
        />

        <MetricCard
          label={tc('statuses.active')}
          value={stats.active}
          icon={Layers}
          color="amber"
          dir="ltr"
        />

        <MetricCard
          label={t('description')}
          value={tc('verified')}
          icon={ShieldCheck}
          color="emerald"
          dir="ltr"
        />
      </div>

      <DataTable 
        columns={columns} 
        data={departments} 
        isLoading={isLoading}
        collectionName="master_data_departments"
        onRowClick={(r: Department) => router.push(`/master-data/departments/${r.id}`)}
        emptyState={
          <EmptyState 
            variant="minimal"
            title={tc('no_data')}
          />
        }
        filters={
          <div className="flex flex-wrap items-end gap-6 w-full py-6 px-8 bg-surface-container-medium/30 rounded-sm">
            <div className="flex flex-col gap-2 min-w-[300px] flex-1">
              <label className="text-label-xs font-semibold uppercase text-muted-foreground/60 ps-1">{tc('search')}</label>
              <div className="relative">
                <Input
                  placeholder={tc('search')}
                  value={search}
                  onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                  className="w-full bg-surface-container-highest/30 border-none h-12 px-12 text-label-sm font-bold rounded-sm shadow-inner shadow-black/20"
                />
                <Search className="absolute start-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40" />
              </div>
            </div>
          </div>
        }
      />
    </div>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { Plus, Search, ArrowRightLeft, Calendar, ShieldCheck, History } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { useFXRates } from '@/features/fx-rates/hooks/useFXRates';
import { useCurrencies } from '@/features/currencies/hooks/useCurrencies';
import { type FXRate, type Currency } from '@/types/master-data';
import { formatRate } from '@/utils/currency';
import { PageHeader } from '@/components/shared/PageHeader';
import { Input } from '@/components/ui/input';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { MetricCard } from '@/components/ui/metric-card';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { EmptyState } from '@/components/shared/EmptyState';
import { ClientOnlyTime } from '@/components/shared/ClientOnlyTime';

export function FXRateListClient({ locale }: { locale: string }) {
  const t = useTranslations('common');
  const tfx = useTranslations('master_data.fx_rates');
  const router = useRouter();
  const [search, setSearch] = useState('');

  const { data, isLoading } = useFXRates();
  const { data: currencies } = useCurrencies();

  const rates = data || [];

  const stats = useMemo(() => {
    return {
      total: rates.length,
      active: rates.filter(r => r.is_active).length,
      lastUpdate: rates.length > 0 
        ? Math.max(...rates.map(r => new Date(r.effective_date).getTime()))
        : null
    };
  }, [rates]);

  const getCurrencyCode = (id: string) => (currencies || []).find((c: Currency) => c.id === id)?.code || id;

  const columns = useMemo<ColumnDef<FXRate, unknown>[]>(() => [
    {
      accessorKey: 'from_currency',
      header: tfx('fields.from_currency'),
      cell: ({ row }) => (
        <div className="flex items-center gap-3">
          <span className="font-bold text-operational-cyan font-mono uppercase px-2 py-0.5 bg-operational-cyan/10 rounded-lg border border-operational-cyan/5">{getCurrencyCode(row.original.from_currency_id)}</span>
          <ArrowRightLeft className="w-3.5 h-3.5 text-muted-foreground/40" />
          <span className="font-bold text-label-sm uppercase px-2 py-0.5 bg-surface-container rounded-lg border border-surface-variant/10">{getCurrencyCode(row.original.to_currency_id)}</span>
        </div>
      )
    },
    {
      accessorKey: 'rate',
      header: tfx('fields.rate'),
      cell: ({ row }) => (
        <div className="flex flex-col">
          <span className="font-mono text-label-sm font-bold text-status-active tabular-nums">
            {formatRate(row.original.rate, locale as 'ar' | 'en', 4)}
          </span>
          <span className="text-label-xxs text-muted-foreground/60 font-medium">
            1 {getCurrencyCode(row.original.from_currency_id)} = {formatRate(row.original.rate, locale as 'ar' | 'en', 4)} {getCurrencyCode(row.original.to_currency_id)}
          </span>
        </div>
      )
    },
    {
      accessorKey: 'effective_date',
      header: tfx('fields.effective_date'),
      cell: ({ row }) => (
        <div className="flex items-center gap-2 text-label-xs font-bold text-muted-foreground bg-surface-container/50 px-2.5 py-1 rounded-lg w-fit">
          <Calendar className="w-3.5 h-3.5 opacity-40 text-operational-cyan" />
          <ClientOnlyTime 
            date={row.original.effective_date} 
            mode="date" 
            locale={locale as 'ar' | 'en'} 
            fallback="--/--/----" 
          />
        </div>
      )
    },
    {
      accessorKey: 'is_active',
      header: t('status'),
      cell: ({ row }) => (
        <StatusBadge status={row.original.is_active ? 'ACTIVE' : 'INACTIVE'} className="rounded-lg px-2.5" />
      )
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end">
          <PermissionGate action="edit" resource="master_data">
          <Button
            variant="ghost"
            size="sm"
            className="text-label-xs font-bold uppercase text-operational-cyan hover:bg-operational-cyan/10 h-9 px-4 rounded-xl transition-all"
            onClick={(e) => {
              e.stopPropagation();
              router.push(`/master-data/fx-rates/${row.original.id}/edit`);
            }}
          >
            {t('edit')}
          </Button>
        </PermissionGate>
      </div>
      )
    }
  ], [t, tfx, router, currencies, locale]);

  const breadcrumbs = [
    { label: t('home'), href: `/dashboard` },
    { label: t('master_data'), href: `/master-data` },
    { label: tfx('title'), href: `/master-data/fx-rates` }
  ];

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="space-y-4">
        <Breadcrumb items={breadcrumbs} />
        <PageHeader 
          title={tfx('title')} 
          description={tfx('description')}
          actions={
            <PermissionGate action="create" resource="master_data">
              <Link href={`/master-data/fx-rates/new`}>
                <Button className="h-11 px-8 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-bold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                  <Plus className="w-3.5 h-3.5 me-2" />
                  {t('create_new')}
                </Button>
              </Link>
            </PermissionGate>
          }
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={tfx('metrics.total_rates')}
          value={stats.total}
          icon={ArrowRightLeft}
          color="cyan"
          dir="ltr"
        />

        <MetricCard
          label={t('active')}
          value={stats.active}
          icon={ShieldCheck}
          color="emerald"
          dir="ltr"
        />

        <MetricCard
          label={tfx('metrics.last_update')}
          value={stats.lastUpdate ? <ClientOnlyTime date={new Date(stats.lastUpdate)} mode="date" locale={locale as 'ar' | 'en'} /> : '—'}
          icon={History}
          color="amber"
          dir="ltr"
        />
      </div>

      <DataTable 
        columns={columns} 
        data={rates} 
        isLoading={isLoading}
        collectionName="master_data_fx_rates"
        emptyState={
          <EmptyState 
            variant="minimal"
            title={t('no_data')}
          />
        }
        filters={
          <div className="flex flex-wrap items-end gap-6 w-full py-4 px-6 bg-surface-container-low/50 border border-surface-variant/10 rounded-sm">
            <div className="flex flex-col gap-2 min-w-[300px] flex-1">
              <label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t('search')}</label>
              <div className="relative">
                <Input
                  placeholder={tfx('search_placeholder')}
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full bg-surface-container-highest/30 border-none h-11 ps-10 text-label-sm font-bold"
                />
                <Search className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40" />
              </div>
            </div>
          </div>
        }
      />
    </div>
  );
}

'use client';

import { useTranslations } from 'next-intl';
import { Upload, Download } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import * as XLSX from 'xlsx';

import { ImportWizardState } from '../types';

interface Step1UploadProps {
 wizard: ImportWizardState;
 locale: string;
}

export function Step1Upload({ wizard, locale: _locale }: Step1UploadProps) {
 const t = useTranslations('master_data.import');
 const tc = useTranslations('common');
 
 const handleFile = (file: File) => {
  if (file && (file.name.endsWith('.xlsx') || file.name.endsWith('.xls'))) {
  const reader = new FileReader();
  reader.onload = (e) => {
  const data = new Uint8Array(e.target?.result as ArrayBuffer);
  const workbook = XLSX.read(data, { type: 'array' });
  const sheetName = workbook.SheetNames[0];
  const worksheet = workbook.Sheets[sheetName];
  const json = XLSX.utils.sheet_to_json(worksheet);
  
  wizard.setFileData(file.name, file.size, json as Record<string, unknown>[]);
  };
  reader.readAsArrayBuffer(file);
  }
 };


 const downloadTemplate = () => {
 let headers: string[] = [];
 let fileName = '';

 if (wizard.importType === 'items') {
 headers = ['sku', 'name_en', 'name_ar', 'category', 'base_unit', 'min_stock', 'reorder_point'];
 fileName = 'items_template.xlsx';
 } else if (wizard.importType === 'uoms') {
 headers = ['code', 'name_en', 'name_ar'];
 fileName = 'uoms_template.xlsx';
 } else if (wizard.importType === 'barcodes') {
 headers = ['barcode', 'item_sku', 'uom_code', 'default_qty'];
 fileName = 'barcodes_template.xlsx';
 }

 const ws = XLSX.utils.aoa_to_sheet([headers]);
 const wb = XLSX.utils.book_new();
 XLSX.utils.book_append_sheet(wb, ws, 'Template');
 XLSX.writeFile(wb, fileName);
 };

 return (
 <div className="max-w-2xl mx-auto flex flex-col gap-8 py-12">
 <Card className="group relative border-dashed border-2 border-muted-foreground/20 bg-muted/5 p-12 flex flex-col items-center gap-6 hover:border-cyan-500/50 hover:bg-cyan-500/5 transition-all duration-500 cursor-pointer overflow-hidden rounded-[2.5rem]">
 <div className="absolute inset-0 bg-gradient-to-br from-cyan-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
 
 <div className="w-20 h-20 rounded-full bg-cyan-500/10 flex items-center justify-center group-hover:scale-110 transition-transform duration-500">
 <Upload className="w-10 h-10 text-cyan-500" />
 </div>

 <div className="text-center relative z-10">
 <h3 className="text-title-sm font-semibold mb-2">{t('drop_file')}</h3>
 <p className="text-label-xs text-muted-foreground font-semibold uppercase opacity-60">
 {t('max_size')}
 </p>
 </div>

 <input 
 type="file" 
 className="absolute inset-0 opacity-0 cursor-pointer" 
 accept=".xlsx,.xls"
 onChange={(e) => {
 const file = e.target.files?.[0];
 if (file) handleFile(file);
 }}
 />
 </Card>

 <div className="flex flex-col gap-4">
 <div className="flex items-center gap-4">
 <div className="h-px flex-1 bg-muted-foreground/10" />
 <span className="text-label-xs font-semibold uppercase text-muted-foreground/30">{tc('or')}</span>
 <div className="h-px flex-1 bg-muted-foreground/10" />
 </div>

 <Button 
 variant="outline" 
 className="h-16 rounded-2xl border-muted-foreground/10 hover:border-cyan-500/40 hover:bg-cyan-500/5 transition-all group overflow-hidden relative"
 onClick={downloadTemplate}
 >
 <div className="absolute inset-0 bg-gradient-to-r from-cyan-500/0 via-cyan-500/5 to-cyan-500/0 -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
 <Download className="w-4 h-4 mr-2 text-cyan-500 group-hover:-translate-y-1 transition-transform" />
 <span className="font-bold">{t('download_template')}</span>
 </Button>
 </div>
 </div>
 );
}

'use client';

import { useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { Database, Loader2, CheckCircle2, AlertCircle, ArrowLeft, ArrowRight } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { cn } from '@/lib/utils';

import { validateImportData } from '@/lib/import/validation';
import { ImportWizardState, ValidationError } from '../types';

interface Step2ValidateProps {
 wizard: ImportWizardState;
 locale: string;
}

export function Step2Validate({ wizard, locale }: Step2ValidateProps) {
 const t = useTranslations('master_data.import');
 const tc = useTranslations('common');

 useEffect(() => {
  // Trigger validation once
  if (wizard.data.length > 0 && !wizard.isValidating && wizard.errors.length === 0) {
   const results = validateImportData(wizard.importType, wizard.data);
   // Wait a bit to show the animation (for UX)
   setTimeout(() => {
    wizard.setValidationResults(results.errors);
   }, 1500);
  }
 }, []);


 if (wizard.isValidating) {
 return (
 <div className="flex flex-col items-center justify-center py-24 gap-8">
 <div className="relative">
 <div className="absolute inset-0 bg-cyan-500/20 blur-3xl rounded-full animate-pulse" />
 <div className="relative">
 <Loader2 className="w-24 h-24 text-cyan-500 animate-spin opacity-20" />
 <Database className="w-10 h-10 text-cyan-500 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-bounce" />
 </div>
 </div>
 <div className="text-center">
 <h3 className="text-headline-lg font-semibold mb-2 bg-gradient-to-br from-foreground to-foreground/60 bg-clip-text text-transparent">
 {t('validating')}
 </h3>
 <p className="text-label-xs text-muted-foreground font-semibold uppercase opacity-60">
 {t('processing_entries', { count: wizard.data.length })}
 </p>
 </div>
 </div>
 );
 }

 const errorCount = wizard.errors.filter((e: ValidationError) => e.severity === 'error').length;
 const warningCount = wizard.errors.filter((e: ValidationError) => e.severity === 'warning').length;

 return (
 <div className="max-w-2xl mx-auto flex flex-col gap-6 py-12">
 <Card className={cn(
 "p-10 rounded-[2.5rem] flex flex-col items-center gap-8 border-none shadow-2xl relative overflow-hidden transition-all duration-700",
 errorCount > 0 ? "bg-red-500/5 shadow-red-500/5" : "bg-emerald-500/5 shadow-emerald-500/5"
 )}>
 {/* Status Icon */}
 <div className={cn(
 "w-24 h-24 rounded-full flex items-center justify-center relative",
 errorCount > 0 ? "bg-red-500/10 text-red-500" : "bg-emerald-500/10 text-emerald-500"
 )}>
 <div className="absolute inset-0 bg-current opacity-10 animate-ping rounded-full" />
 {errorCount > 0 ? <AlertCircle className="w-12 h-12 relative z-10" /> : <CheckCircle2 className="w-12 h-12 relative z-10" />}
 </div>

 <div className="text-center">
 <h3 className="text-headline-lg font-semibold mb-2">
 {t('validation_complete')}
 </h3>
 {errorCount > 0 ? (
 <p className="text-muted-foreground font-medium">{t('errors_found', { count: errorCount })}</p>
 ) : (
 <p className="text-muted-foreground font-medium">{t('no_errors')}</p>
 )}
 </div>

 <div className="grid grid-cols-3 gap-4 w-full">
 <div className="bg-background/40 backdrop-blur-sm p-5 rounded-[1.5rem] flex flex-col items-center border border-foreground/5">
 <span className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-1">{t('total_records')}</span>
 <span className="text-headline-lg font-display font-bold">{wizard.data.length}</span>
 </div>
 <div className="bg-background/40 backdrop-blur-sm p-5 rounded-[1.5rem] flex flex-col items-center border border-foreground/5">
 <span className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-1">{t('errors')}</span>
 <span className={cn("text-headline-lg font-display font-bold", errorCount > 0 ? "text-red-500" : "text-emerald-500/40")}>
 {errorCount}
 </span>
 </div>
 <div className="bg-background/40 backdrop-blur-sm p-5 rounded-[1.5rem] flex flex-col items-center border border-foreground/5">
 <span className="text-label-xxs font-semibold uppercase text-muted-foreground/40 mb-1">{t('warnings')}</span>
 <span className={cn("text-headline-lg font-display font-bold", warningCount > 0 ? "text-amber-500" : "text-muted-foreground/20")}>
 {warningCount}
 </span>
 </div>
 </div>

 <div className="flex gap-4 w-full mt-4">
 <Button 
 variant="outline" 
 className="flex-1 h-14 rounded-2xl border-muted-foreground/10 hover:bg-muted-foreground/5"
 onClick={wizard.reset}
 >
 <ArrowLeft className={cn("w-4 h-4", locale === 'ar' ? "ml-2" : "mr-2")} />
 {tc('cancel')}
 </Button>
 <Button 
 className={cn(
 "flex-1 h-14 rounded-2xl font-semibold uppercase text-label-xs shadow-lg transition-all active:scale-95",
 errorCount > 0 
 ? "bg-red-500 hover:bg-red-600 shadow-red-500/20" 
 : "bg-cyan-500 hover:bg-cyan-600 shadow-cyan-500/20 text-white"
 )}
 onClick={wizard.nextStep}
 >
 {errorCount > 0 ? t('error_step') : t('commit_step')}
 <ArrowRight className={cn("w-4 h-4", locale === 'ar' ? "mr-2 rotate-180" : "ml-2")} />
 </Button>
 </div>
 </Card>
 </div>
 );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter, Link } from '@/i18n/navigation';
import { useTranslations } from 'next-intl';
import { Plus, Package, CheckCircle2, Search, Barcode, ShieldAlert } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DataTable } from '@/components/shared/DataTable/DataTable';
import { ColumnDef } from '@tanstack/react-table';
import { useItems } from '@/features/items/hooks/useItems';
import { type Item } from '@/types/master-data';
import { PageHeader } from '@/components/shared/PageHeader';
import { Breadcrumb } from '@/components/shared/Breadcrumb';
import { MetricCard } from '@/components/ui/metric-card';
import { EmptyState } from '@/components/shared/EmptyState';
import { StatusBadge } from '@/components/shared/StatusBadge';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { Input } from '@/components/ui/input';
import { ErrorState } from '@/components/shared/ErrorState';
import { PageSkeleton } from '@/components/shared/PageSkeleton';

export function ItemListClient({ locale }: { locale: string }) {
  const t = useTranslations('common');
  const ti = useTranslations('master_data.items');
  const router = useRouter();
  const [search, setSearch] = useState('');

  const { data, isLoading, isError, refetch } = useItems({ search });

  const stats = useMemo(() => {
    const items = data?.data ?? [];
    return {
      total: items.length,
      active: items.filter(i => i.is_active).length,
      trackingLots: items.filter(i => i.track_lots).length,
    };
  }, [data]);

  const columns = useMemo<ColumnDef<Item, unknown>[]>(() => [
    { 
      accessorKey: 'code', 
      header: t('code'), 
      cell: ({ row }) => (
        <div className="flex flex-col gap-1">
          <span className="font-mono text-operational-cyan font-bold uppercase text-label-xs bg-operational-cyan/10 px-2 py-0.5 rounded-lg border border-operational-cyan/5 w-fit whitespace-nowrap inline-block min-w-max" dir="ltr">{row.original.code}</span>
          <span className="text-label-xxs text-muted-foreground/60 font-medium font-mono flex items-center gap-1.5 ps-1" dir="ltr">
            <Barcode className="w-3 h-3 opacity-40" />
            {row.original.barcode || '—'}
          </span>
        </div>
      )
    },
    { 
      accessorKey: 'name', 
      header: t('name'), 
      cell: ({ row }) => (
        <div className="flex flex-col gap-0.5">
          <span className="font-bold text-label-sm">{row.original.name_en}</span>
          <span className="text-label-xs text-muted-foreground/60 font-medium" dir="rtl">{row.original.name_ar}</span>
        </div>
      )
    },
    { 
      accessorKey: 'base_unit', 
      header: ti('fields.base_unit'), 
      cell: ({ row }) => (
        <span className="text-label-xs font-bold uppercase text-muted-foreground/80 px-2 py-0.5 bg-surface-container rounded-lg">
          {row.original.primary_uom.code}
        </span>
      )
    },
    {
      accessorKey: 'track_lots', 
      header: ti('fields.track_lots'),
      cell: ({ row }) => row.original.track_lots
        ? <div className="flex items-center gap-1.5 text-operational-cyan font-bold text-label-xxs uppercase bg-operational-cyan/10 px-2.5 py-1 rounded-lg border border-operational-cyan/5 w-fit">
            <div className="w-1.5 h-1.5 rounded-full bg-operational-cyan shadow-[0_0_8px_currentColor]" />
            {t('yes')}
          </div>
        : <div className="flex items-center gap-1.5 text-muted-foreground/40 font-bold text-label-xxs uppercase bg-surface-container px-2.5 py-1 rounded-lg w-fit">
            <div className="w-1.5 h-1.5 rounded-full bg-muted-foreground/20" />
            {t('no')}
          </div>,
    },
    {
      accessorKey: 'is_active', 
      header: t('status'),
      cell: ({ row }) => (
        <StatusBadge status={row.original.is_active ? 'ACTIVE' : 'INACTIVE'} className="rounded-lg px-2.5" />
      ),
    },
    {
      id: 'actions',
      header: '',
      cell: ({ row }) => (
        <div className="flex justify-end gap-3">
          <PermissionGate action="view" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-bold uppercase text-operational-cyan hover:bg-operational-cyan/10 h-9 px-4 rounded-xl transition-all"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/items/${row.original.id}`);
              }}
            >
              {t('view')}
            </Button>
          </PermissionGate>
          <PermissionGate action="edit" resource="master_data">
            <Button 
              variant="ghost" 
              size="sm" 
              className="text-label-xs font-bold uppercase text-status-warning hover:bg-status-warning/10 h-9 px-4 rounded-xl transition-all"
              onClick={(e) => {
                e.stopPropagation();
                router.push(`/master-data/items/${row.original.id}/edit`);
              }}
            >
              {t('edit')}
            </Button>
          </PermissionGate>
        </div>
      ),
    },
  ], [t, ti, router]);

  if (isLoading && !data) {
    return <PageSkeleton variant="list" />;
  }

  if (isError) {
    return (
      <div className="p-8">
        <ErrorState 
          type="server_error"
          onRetry={() => refetch()}
        />
      </div>
    );
  }

  const breadcrumbs = [
    { label: t('home'), href: `/dashboard` },
    { label: t('master_data'), href: `/master-data` },
    { label: ti('title'), href: `/master-data/items` }
  ];

  return (
    <div className="p-8 max-w-[1600px] mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      <div className="space-y-4">
        <Breadcrumb items={breadcrumbs} />
        <PageHeader 
          title={ti('title')} 
          description={ti('description')}
          actions={
            <PermissionGate action="create" resource="master_data">
              <Link href={`/master-data/items/new`}>
                <Button className="h-11 px-8 bg-operational-cyan hover:bg-operational-cyan/90 text-white text-label-xs font-semibold uppercase rounded-xl transition-all shadow-lg shadow-operational-cyan/20">
                  <Plus className="w-3.5 h-3.5 me-2" />
                  {t('create_new')}
                </Button>
              </Link>
            </PermissionGate>
          }
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard
          label={ti('metrics.total_items')}
          value={stats.total}
          icon={Package}
          color="cyan"
        />

        <MetricCard
          label={t('active')}
          value={stats.active}
          icon={CheckCircle2}
          color="emerald"
        />

        <MetricCard
          label={ti('metrics.tracking_lots')}
          value={stats.trackingLots}
          icon={ShieldAlert}
          color="amber"
        />
      </div>

      <DataTable 
        columns={columns} 
        data={data?.data ?? []} 
        isLoading={isLoading}
        collectionName="master_data_items"
        emptyState={
          <EmptyState 
            variant="minimal"
            title={t('no_data')}
          />
        }
        onRowClick={(r: Item) => router.push(`/master-data/items/${r.id}`)}
        filters={
          <div className="flex flex-wrap items-end gap-6 w-full py-4 px-6 bg-surface-container-low/50 border border-surface-variant/10 rounded-sm">
            <div className="flex flex-col gap-2 min-w-[300px] flex-1">
              <label className="text-label-xs font-semibold uppercase text-muted-foreground/60">{t('search')}</label>
              <div className="relative">
                <Input
                  placeholder={ti('search_placeholder')}
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full bg-surface-container-highest/30 border-none h-11 ps-10 text-label-sm font-bold"
                />
                <Search className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground/40" />
              </div>
            </div>
          </div>
        }
      />
    </div>
  );
}

'use client';

