  emptyDescription?: string;
  filters?: React.ReactNode;
  onRowClick?: (row: T) => void;
  collectionName?: ResourceType;
  className?: string;
}

/**
 * PrecisionTable component
 * Implements 'The Precision Ledger' design philosophy:
 * - Tonal Architecture (No 1px solid borders)
 * - IBM Plex Sans Arabic typography
 * - High-density spacing
 * - Glassmorphism effects where appropriate
 */
export function PrecisionTable<T>({
  data,
  columns,
  isLoading,
  isError,
  onRetry,
  pagination,
  onExport,
  emptyTitle,
  emptyDescription,
  filters,
  onRowClick,
  collectionName,
  className,
}: PrecisionTableProps<T>) {
  return (
    <div className={cn("w-full precision-table-container", className)}>
      <DataTable
        data={data}
        columns={columns}
        isLoading={isLoading}
        isError={isError}
        onRetry={onRetry}
        pagination={pagination}
        onExport={onExport}
        emptyTitle={emptyTitle}
        emptyDescription={emptyDescription}
        filters={filters}
        onRowClick={onRowClick}
        collectionName={collectionName}
        // Precision-specific overrides for high-density
        rowClassName={(row) => cn(
          "group transition-all duration-150 ease-out",
          onRowClick ? "cursor-pointer" : "",
        )}
        enableVirtualization={data.length > 50}
        virtualRowHeight={42} // Slightly tighter for precision
      />
      
      <style jsx global>{`
        .precision-table-container thead th {
          @apply h-12 text-[11px] tracking-[0.12em];
        }
        
        .precision-table-container tbody td {
          @apply py-2.5 text-[13px] leading-tight;
        }

        /* RTL Specific adjustments for typography */
        [dir="rtl"] .precision-table-container {
          font-family: var(--font-ibm-plex-arabic), sans-serif;
        }
      `}</style>
    </div>
  );
}

