"use client"
// use no memo

import * as React from "react"
import {
 ColumnDef,
 flexRender,
 getCoreRowModel,
 useReactTable,
 getPaginationRowModel,
 getFilteredRowModel,
 SortingState,
 getSortedRowModel,
 ColumnFiltersState,
} from "@tanstack/react-table"

import {
 Table,
 TableBody,
 TableCell,
 TableHead,
 TableHeader,
 TableRow,
} from "@/components/ui/table"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { ChevronLeft, ChevronRight, Download, Search } from "lucide-react"

// A generic translation placeholder mechanism since this is a client component
// and next-intl might not be universally available in simple stories.
// Usually, we'd inject this from the parent via props or use the hook directly.
import { useTranslations } from "next-intl"

interface DataTableProps<TData, TValue> {
 columns: ColumnDef<TData, TValue>[]
 data: TData[]
 searchKey?: string
 searchPlaceholder?: string
 enableExport?: boolean
 onExport?: () => void
}

export function DataTable<TData, TValue>({
 columns,
 data,
 searchKey,
 searchPlaceholder,
 enableExport,
 onExport,
}: DataTableProps<TData, TValue>) {
 const [sorting, setSorting] = React.useState<SortingState>([])
 const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([])
 const t = useTranslations("common");

 const table = useReactTable({
 data,
 columns,
 getCoreRowModel: getCoreRowModel(),
 getPaginationRowModel: getPaginationRowModel(),
 onSortingChange: setSorting,
 getSortedRowModel: getSortedRowModel(),
 onColumnFiltersChange: setColumnFilters,
 getFilteredRowModel: getFilteredRowModel(),
 state: {
 sorting,
 columnFilters,
 },
 })

 return (
 <div className="space-y-4">
 <div className="flex items-center justify-between">
 {searchKey ? (
 <div className="relative max-w-sm w-full">
 <Search className="absolute start-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
 <Input
  placeholder={searchPlaceholder || t("table.search")} value={(table.getColumn(searchKey)?.getFilterValue() as string) ?? ""} onChange={(event) =>
 table.getColumn(searchKey)?.setFilterValue(event.target.value)
 }
 className="max-w-sm ps-10"
 />
 </div>
 ) : <div />}
 {enableExport && (
 <Button variant="outline" onClick={onExport} className="bg-surface-container-low hover:bg-surface-container-high">
 <Download className="me-2 h-4 w-4" />
 {t("table.export")}
 </Button>
 )}
 </div>
 <div className="rounded-[var(--radius)] bg-surface-container-low overflow-hidden shadow-sm">
 <Table>
 <TableHeader>
 {table.getHeaderGroups().map((headerGroup) => (
 <TableRow key={headerGroup.id}>
 {headerGroup.headers.map((header) => {
 return (
 <TableHead key={header.id}>
 {header.isPlaceholder
 ? null
 : flexRender(
 header.column.columnDef.header,
 header.getContext()
 )}
 </TableHead>
 )
 })}
 </TableRow>
 ))}
 </TableHeader>
 <TableBody>
 {table.getRowModel().rows?.length ? (
 table.getRowModel().rows.map((row) => (
 <TableRow
 key={row.id}
 data-state={row.getIsSelected() && "selected"}
 >
 {row.getVisibleCells().map((cell) => (
 <TableCell key={cell.id}>
 {flexRender(cell.column.columnDef.cell, cell.getContext())}
 </TableCell>
 ))}
 </TableRow>
