'use client';

import { type ReactNode } from 'react';
import { useTranslations } from 'next-intl';
import { Button } from '@/components/ui/button';
import { ArrowLeft } from 'lucide-react';
import { PermissionGate } from '@/components/shared/PermissionGate';
import { FormFooter } from '@/components/shared/FormFooter';
import { type ResourceType, type ActionType } from '@/types/rbac';

interface Props {
  title: string;
  children: ReactNode;
  isSaving?: boolean;
  onSubmit?: () => void;
  onCancel?: () => void;
  resource?: ResourceType;
  saveAction?: ActionType;
  hideSave?: boolean;
  saveDisabled?: boolean;
  isDirty?: boolean;
  isValid?: boolean;
  backHref?: string;
  headerActions?: ReactNode;
}

export function MasterDataFormLayout({ 
  title, 
  children, 
  isSaving = false, 
  onSubmit = () => {},
  onCancel = () => {},
  resource = 'master_data',
  saveAction = 'create',
  hideSave = false,
  saveDisabled = false,
  isDirty = true,
  isValid = true,
  headerActions,
  backHref
}: Props) {
  const t = useTranslations('master_data.common');

  return (
    <div className="p-8 max-w-[1000px] mx-auto pb-32 space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-200">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-12">
        <div className="flex items-center gap-6">
          <Button 
            variant="ghost" 
            size="icon" 
            onClick={onCancel}
            className="w-12 h-12 rounded-xl bg-surface-container-low hover:bg-operational-cyan/10 text-muted-foreground hover:text-operational-cyan transition-all group border-none"
          >
            <ArrowLeft className="w-5 h-5 rtl:rotate-180 group-hover:-translate-x-1 rtl:group-hover:translate-x-1 transition-transform" />
          </Button>
          <div className="space-y-1">
            <h1 className="text-headline-lg font-semibold text-foreground uppercase">{title}</h1>
            <p className="text-label-xs text-muted-foreground/40 uppercase font-semibold">{t('asset_metadata')}</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          {headerActions}
        </div>
      </div>

      <div className="bg-surface-container-lowest rounded-2xl p-10 relative overflow-hidden">
        {/* Subtle grid pattern background */}
        <div className="absolute inset-0 opacity-[0.01] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]" />
        
        <div className="relative z-10 max-w-5xl mx-auto space-y-8">
          {children}
        </div>
      </div>

      <div className="flex items-center justify-between px-10 py-6 bg-surface-container-low/40 rounded-2xl">
        <span className="text-label-xs text-muted-foreground/40 uppercase font-semibold">{t('confidential_data')}</span>
        <div className="flex gap-4 items-center">
          <div className="flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-operational-cyan animate-pulse" />
            <span className="text-label-xxs text-operational-cyan/60 font-semibold uppercase">{t('secure_connection')}</span>
          </div>
        </div>
      </div>

      {!hideSave && (
        <PermissionGate action={saveAction} resource={resource}>
          <FormFooter 
            onCancel={onCancel}
            onSubmit={onSubmit}
            isSaving={isSaving}
            isDirty={isDirty}
            isValid={isValid}
            canSubmit={!saveDisabled}
          />
        </PermissionGate>
      )}
    </div>
  );
}

import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useSafeMutation } from '@/core/concurrency/useSafeMutation';
import { apiClient } from '@/lib/api/client';
import { z } from 'zod';
import { 
  StocktakeSessionSchema, 
  CreateStocktakeDTO, 
  SubmitCountDTO,
  StocktakeItemSchema
} from '../types/stocktake';

const StocktakeListSchema = z.object({
  data: z.array(StocktakeSessionSchema.omit({ items: true })),
  meta: z.object({
    page: z.number(),
    page_size: z.number(),
    total: z.number(),
    total_pages: z.number(),
  }),
});

export function useStocktakes() {
  return useQuery({
    queryKey: ['stocktakes'],
    queryFn: ({ signal }) => apiClient.get('/stocktake/sessions', StocktakeListSchema, signal),
  });
}

export function useStocktake(id: string) {
  return useQuery({
    queryKey: ['stocktakes', id],
    queryFn: ({ signal }) => apiClient.get(`/stocktake/sessions/${id}`, StocktakeSessionSchema, signal),
    enabled: !!id,
  });
}

export function useCreateStocktake() {
  const qc = useQueryClient();
  return useSafeMutation({
    mutationFn: ({ data, signal }: { data: CreateStocktakeDTO; signal?: AbortSignal }) => 
      apiClient.post('/stocktake/sessions', StocktakeSessionSchema, data, signal),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['stocktakes'] }),
  });
}

export function useStartStocktake(options?: { onConflict?: () => void }) {
  const qc = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: ({ id, signal }: { id: string; signal?: AbortSignal }) => 
      apiClient.post(`/stocktake/sessions/${id}/start`, StocktakeSessionSchema, null, signal),
    onSuccess: (_, { id }) => {
      qc.invalidateQueries({ queryKey: ['stocktakes'] });
      qc.invalidateQueries({ queryKey: ['stocktakes', id] });
      qc.invalidateQueries({ queryKey: ['warehouse-lock'] });
    },
  });
}

export function useBeginCounting(options?: { onConflict?: () => void }) {
  const qc = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: ({ id, signal }: { id: string; signal?: AbortSignal }) => 
      apiClient.post(`/stocktake/sessions/${id}/count`, StocktakeSessionSchema, null, signal),
    onSuccess: (_, { id }) => {
      qc.invalidateQueries({ queryKey: ['stocktakes'] });
      qc.invalidateQueries({ queryKey: ['stocktakes', id] });
    },
  });
}

export function useCompleteCounting(options?: { onConflict?: () => void }) {
  const qc = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: ({ id, signal }: { id: string; signal?: AbortSignal }) => 
      apiClient.post(`/stocktake/sessions/${id}/submit`, StocktakeSessionSchema, null, signal),
    onSuccess: (_, { id }) => {
      qc.invalidateQueries({ queryKey: ['stocktakes'] });
      qc.invalidateQueries({ queryKey: ['stocktakes', id] });
    },
  });
}

export function useSubmitVariance(options?: { onConflict?: () => void }) {
  const qc = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: ({ id, items, signal }: { id: string; items: { line_id: string; variance_reason?: string }[]; signal?: AbortSignal }) => 
      apiClient.post(`/stocktake/sessions/${id}/review_variance`, StocktakeSessionSchema, { items }, signal),
    onSuccess: (_, { id }) => {
      qc.invalidateQueries({ queryKey: ['stocktakes'] });
      qc.invalidateQueries({ queryKey: ['stocktakes', id] });
    },
  });
}

export function useUpdateItemCount(options?: { onConflict?: () => void }) {
  const qc = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: ({ stocktakeId, itemId: _itemId, lineId, countedQty, varianceReason, signal }: { stocktakeId: string; itemId: string; lineId: string; countedQty: number; varianceReason?: string; signal?: AbortSignal }) => 
      apiClient.put(`/stocktake/sessions/${stocktakeId}/items/${lineId}`, StocktakeItemSchema, { 
        counted_qty: countedQty, 
        variance_reason: varianceReason 
      }, signal),
    onSuccess: (_, { stocktakeId }) => {
      qc.invalidateQueries({ queryKey: ['stocktakes', stocktakeId] });
    },
  });
}

/**
 * @deprecated Use useUpdateItemCount for real-time saving. 
 * This remains for bulk submission if needed by legacy parts of the UI.
 */
export function useSubmitCounts(options?: { onConflict?: () => void }) {
  const qc = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
    mutationFn: ({ dto, signal }: { dto: SubmitCountDTO; signal?: AbortSignal }) => 
      apiClient.post(`/stocktake/sessions/${dto.stocktake_id}/submit`, StocktakeSessionSchema, dto, signal),
    onSuccess: (_, { dto }) => {
      qc.invalidateQueries({ queryKey: ['stocktakes'] });
      qc.invalidateQueries({ queryKey: ['stocktakes', dto.stocktake_id] });
    },
  });
}

export function useApproveStocktake(options?: { onConflict?: () => void }) {
  const qc = useQueryClient();
  return useSafeMutation({
    onConflict: options?.onConflict,
