      apiClient.post(`/stocktake/sessions/${id}/reject`, StocktakeSessionSchema, { comment }, signal),
    onSuccess: (_, { id }) => {
      qc.invalidateQueries({ queryKey: ['stocktakes'] });
      qc.invalidateQueries({ queryKey: ['stocktakes', id] });
    },
